def _probe(host, port, t=2):
    import socket as _s
    try:
        with _s.create_connection((host, int(port)), timeout=t): return True
    except Exception:
        return False

def db_list():
    a = _load_dbassets()
    for x in a:
        x["online"] = _probe(x.get("host","127.0.0.1"), x.get("port",3306))
    return {"ok": True, "assets": a}

def db_rm(name):
    a = [x for x in _load_dbassets() if x.get("name") != name]
    _save_dbassets(a); return {"ok": True}

def _connect(rec):
    t = rec["type"]
    if t == "mysql":
        import pymysql
        return pymysql.connect(host=rec["host"], port=int(rec["port"]), user=rec["user"],
                               password=rec["pwd"], database=rec["database"] or None,
                               connect_timeout=8, charset="utf8mb4")
    if t == "postgres":
        import psycopg2
        return psycopg2.connect(host=rec["host"], port=int(rec["port"]), user=rec["user"],
                                password=rec["pwd"], dbname=rec["database"] or "postgres", connect_timeout=8)
    raise ValueError("type")

def db_query(rec, sql, limit=200):
    try:
        if rec["type"] == "mysql":
            conn = _connect(rec); cur = conn.cursor()
            cur.execute(sql); rows = cur.fetchmany(limit)
            cols = [d[0] for d in cur.description] if cur.description else []
            conn.close(); return {"ok": True, "cols": cols, "rows": [list(r) for r in rows], "n": len(rows)}
        elif rec["type"] == "postgres":
            conn = _connect(rec); cur = conn.cursor()
            cur.execute(sql); rows = cur.fetchmany(limit)
            cols = [d[0] for d in cur.description] if cur.description else []
            conn.close(); return {"ok": True, "cols": cols, "rows": [list(r) for r in rows], "n": len(rows)}
        return {"ok": False, "error": "unsupported"}
    except Exception as e:
        return {"ok": False, "error": str(e)[:300]}

def redis_keys(rec, pattern="*"):
    try:
        import redis
        r = redis.Redis(host=rec["host"], port=int(rec["port"]), password=rec["pwd"] or None,
                        db=int(rec.get("database") or 0), socket_timeout=8)
        keys = r.keys(pattern)
        out = []
        for k in keys[:200]:
            try: t = r.type(k).decode()
            except Exception: t = "?"
            out.append({"key": k.decode(errors="replace"), "type": t})
        return {"ok": True, "keys": out}
    except Exception as e:
        return {"ok": False, "error": str(e)[:300]}

