JOBGROUPS_FILE = DATA + "/jobgroups.json"
def job_groups():
    gs = []
    if os.path.exists(JOBGROUPS_FILE):
        try:
            a = json.load(open(JOBGROUPS_FILE))
            if isinstance(a, list): gs = a
        except Exception: gs = []
    for r in _load_jobs():
        g = r.get("group") or "默认分组"
        if g not in gs: gs.append(g)
    if "默认分组" not in gs: gs.insert(0, "默认分组")
    return gs
def _save_job_groups(gs): json.dump(gs, open(JOBGROUPS_FILE, "w"), ensure_ascii=False)
def job_group_add(name):
    name = (name or "").strip()
    if not name: return {"ok": False, "error": "need name"}
    gs = job_groups()
    if name in gs: return {"ok": False, "error": "分组已存在"}
    gs.append(name); _save_job_groups(gs); return {"ok": True, "groups": gs}
def job_group_rm(name):
    if name == "默认分组": return {"ok": False, "error": "默认分组不可删除"}
    gs = [g for g in job_groups() if g != name]; _save_job_groups(gs)
    j = _load_jobs()
    for r in j:
        if r.get("group") == name: r["group"] = "默认分组"
    _save_jobs(j)
    return {"ok": True, "groups": job_groups()}

