# 后台调度线程: 秒级周期扫描, cron 简化为 "interval秒" 或 "HH:MM 每天"
_job_thread = None
def _job_worker():
    import threading
    def loop():
        while True:
            for r in _load_jobs():
                if not r.get("enabled"): continue
                sched = r.get("sched","")
                if sched.isdigit():  # 周期秒
                    last = r.get("last") or 0; now=int(time.time())
                    if now-last >= int(sched):
                        _run_job(r); _mark(r, now)
                elif len(sched) == 5 and sched[2] == ":":  # HH:MM 每天
                    now = time.time()
                    if time.strftime("%H:%M") == sched and now - (r.get("last") or 0) > 60:
                        _run_job(r); _mark(r, int(now))
            time.sleep(2)
    t = threading.Thread(target=loop, daemon=True); t.start(); return t

def _job_log(name, rc, out, start, end):
    """任务日志: 每次计划任务执行追加一条 {name,status,start,end,duration,message} 到 data/joblog.json(最多 500 条)"""
    f = DATA + "/joblog.json"
    try: arr = json.loads(open(f).read() or "[]")
    except Exception: arr = []
    if not isinstance(arr, list): arr = []
    arr.append({"name": name, "status": "Success" if rc == 0 else "Failed",
                "start": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(start)), "end": end,
                "duration": "%s" % ("%.1fs" % max(0.0, time.time() - start)),
                "message": (out or "").strip()[-300:]})
    json.dump(arr[-200:], open(f, "w"), ensure_ascii=False)

def _run_job(r):
    _t0 = time.time(); _out = ""; _rc = 0
    try:
        res = _sp.run(["bash","-lc", r["cmd"]], capture_output=True, text=True, timeout=300,
                      cwd=DATA)
        _rc = res.returncode; _out = res.stdout + res.stderr
    except Exception as e:
        _rc = -1; _out = f"ERR {e}"
    r["last_rc"]=_rc; r["last_out"]=_out[-400:]
    try: _job_log(r["name"], _rc, _out, _t0, time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(time.time())))
    except Exception: pass
    log_event("jobs", r["last_rc"]==0 and "ok" or "err", f"job {r['name']} rc={r['last_rc']}")
    return {"ok": True, "rc": r["last_rc"], "out": r["last_out"]}
def _mark(r, now):
    j=_load_jobs()
    for x in j:
        if x["name"]==r["name"]: x["last"]=now; x["last_rc"]=r.get("last_rc"); x["last_out"]=r.get("last_out","")
    _save_jobs(j)

