def _skills_scan_path(base):
    """对真实目录做静态安全检查: 逐文件匹配高风险模式。"""
    rules = [(r"\brm\s+-rf\s+/", "高", "危险删除命令"),
             (r"curl[^\n|]*\|\s*(ba)?sh", "高", "远程脚本直接执行"),
             (r"wget[^\n|]*\|\s*(ba)?sh", "高", "远程脚本直接执行"),
             (r"\bsudo\b", "中", "提权执行"),
             (r"\beval\s*\(", "中", "动态代码执行"),
             (r"base64\s+-d", "中", "编码载荷解码"),
             (r"chmod\s+777", "中", "过宽权限"),
             (r"~/\.ssh|id_rsa|\.aws/credentials|OPENAI_API_KEY|ANTHROPIC_API_KEY", "高", "疑似读取凭据")]
    findings, nfiles = [], 0
    if os.path.isfile(base):
        files = [base]
    elif os.path.isdir(base):
        files = []
        for root, _dirs, fs in os.walk(base):
            for fn in fs:
                files.append(os.path.join(root, fn))
    else:
        return None
    for f in files:
        nfiles += 1
        try:
            txt = open(f, encoding="utf-8", errors="replace").read()
        except Exception:
            continue
        for ln_no, ln in enumerate(txt.splitlines(), 1):
            for pat, lv, title in rules:
                if re.search(pat, ln):
                    findings.append({"level": lv, "rule": title,
                                     "file": os.path.relpath(f, base if os.path.isdir(base) else os.path.dirname(base)),
                                     "line": ln_no, "text": ln.strip()[:160]})
    return {"files": nfiles, "findings": findings}


