def _client_geo():
    """登录 IP / 归属地（1Panel login_logs 的 ip + address 两列）。"""
    ip = (request.headers.get("X-Real-IP") or request.headers.get("X-Forwarded-For")
          or request.remote_addr or "").split(",")[0].strip()
    if ip.startswith("::ffff:"): ip = ip[7:]
    if ip in ("127.0.0.1", "::1", "localhost"): return "127.0.0.1", "本地"
    if ip.startswith("192.168.") or ip.startswith("10.") or re.match(r"^172\.(1[6-9]|2\d|3[01])\.", ip):
        return ip, "内网 IP"
    return ip, "未知"

def _client_agent():
    return (request.headers.get("User-Agent") or "")[:512]

def _op_log(source, operate, user=None, status="Success", detail_zh="", detail_en="", message=""):
    """操作日志一行（对应 1Panel operation_logs: source/operate/user/node/status/detail_zh/detail_en/message）。"""
    if user is None:
        try: user = _session_user(request.headers) or "admin"
        except Exception: user = "admin"
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    with _LOG_LOCK:
        c = db(); c.execute("""CREATE TABLE IF NOT EXISTS operation_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT, operate TEXT, user TEXT,
            node TEXT, status TEXT, detail_zh TEXT, detail_en TEXT, message TEXT, created_at TEXT)""")
        c.execute("""INSERT INTO operation_logs(source,operate,user,node,status,detail_zh,detail_en,message,created_at)
                     VALUES(?,?,?,?,?,?,?,?,?)""",
                  (source, operate, user, "local", status, detail_zh, detail_en, message or "",
                   now if now[0].isdigit() else time.strftime("%Y-%m-%d %H:%M:%S")))
        c.commit()

def _login_log(user, status="Success", message=""):
    ip, area = _client_geo()
    now = time.strftime("%Y-%m-%d %H:%M:%S")
    with _LOG_LOCK:
        c = db(); c.execute("""CREATE TABLE IF NOT EXISTS login_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT, address TEXT, user TEXT,
            agent TEXT, status TEXT, message TEXT, created_at TEXT)""")
        c.execute("INSERT INTO login_logs(ip,address,user,agent,status,message,created_at) VALUES(?,?,?,?,?,?,?)",
                  (ip, area, user, _client_agent(), status, message or "",
                   now if now[0].isdigit() else time.strftime("%Y-%m-%d %H:%M:%S")))
        c.commit()

def _audit(level, who, msg, source="settings", operate="edit", detail_en="", message=""):
    """兼容旧调用：写入 1Panel 风格的 operation_logs（失败级别记 Failed）。"""
    st = "Failed" if level in ("warn", "err", "error") else "Success"
    _op_log(source, operate, user=who, status=st, detail_zh=msg, detail_en=detail_en, message=message)

def do_login(user, pwd):
    u = _load_users()
    if user in u and u[user]["pwd"] == pwd:
        tok = uuid.uuid4().hex
        SESS[tok] = user
        _save_sess()
        _login_log(user, "Success")
        return {"ok": True, "token": tok, "role": u[user]["role"], "name": user}
    msg = "用户名或密码错误" if user in u else "用户名不存在"
    _login_log(user, "Failed", msg)
    return {"ok": False, "error": "bad user/pass"}

