def auth_test(mode="conn", user="", pwd=""):
    """真实 LDAP 探测；未安装 ldap3 或地址为空时返回明确错误。"""
    d = auth_load()
    srv = (d.get("server") or "").strip()
    if not srv: return {"ok": False, "error": "请先填写服务端地址"}
    try:
        import ldap3
    except Exception:
        return {"ok": False, "error": "服务端未安装 ldap3 模块，无法探测"}
    try:
        tls = None
        if d.get("skipTls"):
            import ssl
            tls = ldap3.Tls(validate=ssl.CERT_NONE)
        s = ldap3.Server(srv, get_info=ldap3.NONE, connect_timeout=max(1, int(d.get("timeout", 10))), tls=tls)
        c = ldap3.Connection(s, user=(d.get("binddn") or None), password=(d.get("bindpwd") or None), auto_bind=True)
        if mode == "login":
            if not user or not pwd: c.unbind(); return {"ok": False, "error": "请填写测试用户名与密码"}
            flt = (d.get("filter") or "(uid=%(user)s)") % {"user": user}
            c.search(d.get("basedn") or "", flt, attributes=ldap3.ALL_ATTRIBUTES)
            hit = bool(c.entries)
            c.unbind()
            return {"ok": hit, "msg": "登录测试成功" if hit else "未匹配到用户", "error": "" if hit else "未匹配到用户"}
        c.unbind()
        return {"ok": True, "msg": "连接成功"}
    except Exception as e:
        return {"ok": False, "error": str(e)[:200]}

