# ---------- 虚拟机管理 (KVM / libvirt) ----------
def _kvm_uri():
    """优先 system 连接(专业版用 root 管理), 不可用时回落当前用户的 session 连接。"""
    try:
        if os.geteuid() == 0 or os.access("/var/run/libvirt/libvirt-sock", os.W_OK):
            return "qemu:///system"
    except Exception:
        pass
    return "qemu:///session"


def _kvm_run(args, stdin=None):
    """跑一条 virsh 命令, 返回 (rc, 输出文本)。所有子页共用。"""
    cmd = ["timeout", "10", "virsh", "-c", _kvm_uri()] + args
    try:
        r = _sp.run(cmd, input=stdin, capture_output=True, text=True, timeout=15)
        out = (r.stdout or "") + (r.stderr or "")
        return r.returncode, out.strip()
    except Exception as e:
        return 1, str(e)


def _kvm_mask(prefix):
    try:
        n = int(prefix)
    except Exception:
        n = 24
    n = max(0, min(32, n))
    bits = (0xFFFFFFFF << (32 - n)) & 0xFFFFFFFF
    return ".".join(str((bits >> sh) & 0xFF) for sh in (24, 16, 8, 0))


def _kvm_image_dir():
    d = os.path.join(DATA, "kvm_images")
    return d


def _kvm_tbl(out, mincols=2):
    """把 virsh 的表格输出解析成二维数组 (跳过分隔线与表头)。"""
    rows = []
    for ln in (out or "").splitlines():
        t = ln.strip()
        if not t or set(t) <= set("-+ "): continue
        parts = re.split(r"\s{2,}", t)
        if len(parts) < mincols: continue
        rows.append(parts)
    return rows[1:] if rows else []


def _kvm_payload():
    """整页数据: 环境探测 + 虚拟机/存储池/网络/镜像/模板 的真实清单。"""
    cpu = ""
    try:
        cpu = open("/proc/cpuinfo").read().lower()
    except Exception:
        pass
    hw = ("vmx" in cpu) or ("svm" in cpu)
    dev = os.path.exists("/dev/kvm")
    virsh = _sp.run(["bash", "-lc", "command -v virsh >/dev/null 2>&1 && echo yes || echo no"],
                    capture_output=True, text=True, timeout=5).stdout.strip() == "yes"
    qemu = _sp.run(["bash", "-lc", "command -v qemu-system-x86_64 qemu-kvm 2>/dev/null | head -1"],
                   capture_output=True, text=True, timeout=5).stdout.strip()
    lib_ok = False; lib_err = ""
    vms = []; pools = []; nets = []
    if virsh:
        rc, out = _kvm_run(["list", "--all"])
        if rc == 0:
            lib_ok = True
            for p in _kvm_tbl(out, 2):
                if not p[0].isdigit(): continue
                vms.append({"id": p[0], "name": p[1], "state": p[2] if len(p) > 2 else ""})
            rc2, o2 = _kvm_run(["pool-list", "--all"])
            if rc2 == 0:
                for p in _kvm_tbl(o2, 2):
                    if len(p) < 2: continue
                    pools.append({"name": p[0], "state": p[1],
                                  "autostart": p[2] if len(p) > 2 else "no"})
            rc3, o3 = _kvm_run(["net-list", "--all"])
            if rc3 == 0:
                for p in _kvm_tbl(o3, 2):
                    if len(p) < 2: continue
                    nets.append({"name": p[0], "state": p[1],
                                 "autostart": p[2] if len(p) > 2 else "no"})
        else:
            lib_err = (out or "").strip().splitlines()
    images = []
    d = _kvm_image_dir()
    try:
        for fn in sorted(os.listdir(d)):
            fp = os.path.join(d, fn)
            if os.path.isfile(fp):
                images.append({"name": fn, "size": os.path.getsize(fp),
                               "time": time.strftime("%Y-%m-%d %H:%M:%S",
                                                     time.localtime(os.path.getmtime(fp)))})
    except Exception:
        pass
    running = sum(1 for v in vms if "run" in v["state"])
    stopped = sum(1 for v in vms if "shut" in v["state"] or "off" in v["state"])
    creating = sum(1 for v in vms if "create" in v["state"])
    return {"ok": bool(hw and dev and lib_ok), "hw": hw, "dev": dev, "virsh": virsh,
            "qemu": qemu, "lib_ok": lib_ok, "uri": _kvm_uri(),
            "msg": (lib_err[0] if lib_err else ("未检测到可用的 KVM 硬件虚拟化能力。" if not (hw and dev) else "")),
            "vms": len(vms), "running": running, "stopped": stopped, "creating": creating,
            "pools": len(pools), "nets": len(nets), "images": len(images),
            "list": vms, "poolList": pools, "netList": nets, "imageList": images,
            "imageDir": _kvm_image_dir(), "risk": (0 if (hw and dev and lib_ok) else 1),
            "error": None if (hw and dev and lib_ok) else "no kvm"}


def col_rm(name, key, val):
    rows = [r for r in _col(name) if r.get(key) != val]; _save_col(name, rows)
    _audit("info", "admin", f"删除 [{val}]", source=_COL_SRC.get(name, "xapp"), operate="delete", detail_en=f"Delete [{val}]")
    return {"ok": True}


# ---------- 模型账号  ----------
def _models_probe(rec):
    """请求供应商 /models 接口。成功返回真实模型 ID 列表, 失败返回真实错误, 不伪造。"""
    import urllib.request as _ur
    base = (rec.get("base_url") or "").strip().rstrip("/")
    key = (rec.get("api_key") or "").strip()
    typ = (rec.get("api_type") or "openai-completions").strip()
    if not base:
        return {"ok": False, "msg": "Base URL 为空"}
    url = base + "/models"
    hdrs = {"Accept": "application/json"}
    if typ.startswith("anthropic"):
        hdrs["x-api-key"] = key
        hdrs["anthropic-version"] = "2023-06-01"
    elif typ.startswith("gemini"):
        url = base + "/models?key=" + urllib.parse.quote(key)
    elif key:
        hdrs["Authorization"] = "Bearer " + key
    try:
        req = _ur.Request(url, headers=hdrs)
        with _ur.urlopen(req, timeout=8) as r:
            raw = r.read().decode("utf-8", "replace")
            code = r.status
    except Exception as e:
        code = getattr(e, "code", None)
        body = ""
        try:
            body = e.read().decode("utf-8", "replace")[:160]
        except Exception:
            pass
        msg = ("HTTP %s %s" % (code, body)).strip() if code else ("连接失败: %s" % e)
        return {"ok": False, "msg": msg}
    ids = []
    try:
        j = json.loads(raw)
        arr = j.get("data") if isinstance(j, dict) else j
        if isinstance(arr, dict):
            arr = arr.get("models") or []
        for it in (arr or []):
            if isinstance(it, dict):
                mid = it.get("id") or it.get("name") or it.get("model")
                if mid:
                    ids.append(str(mid))
            elif isinstance(it, str):
                ids.append(it)
    except Exception:
        pass
    return {"ok": True, "code": code, "msg": "HTTP %s，获取到 %d 个模型" % (code, len(ids)), "models": ids}


# ---------- 应用高可用 (MySQL / PostgreSQL / Redis) ----------
HA_TYPES = [("MySQL", ("mysql", "mariadb")),
            ("PostgreSQL", ("postgres", "postgresql")),
            ("Redis", ("redis",))]


def _ha_node_state(node):
    """节点地址 host:port， TCP 探测；失败即未连接，不伪造。"""
    try:
        host, _, port = (node or "").rpartition(":")
        if not host:
            return "未连接"
        return "已连接" if _probe(host, int(port), 1.5) else "未连接"
    except Exception:
        return "未连接"


def _ha_nodes_of(rec):
    nodes = rec.get("nodes") or []
    if isinstance(nodes, str):
        nodes = [x.strip() for x in nodes.split(",") if x.strip()]
    return [n for n in nodes if n]


def _ha_payload():
    """集群清单(节点逐个探测) + 各类型已安装实例(来自数据库资产)。"""
    apps = _load_dbassets()
    clusters = []
    for r in _col("ha"):
        nodes = _ha_nodes_of(r)
        states = [{"addr": n, "state": _ha_node_state(n)} for n in nodes]
        up = sum(1 for x in states if x["state"] == "已连接")
        if not states:
            st = "未配置"
        elif up == len(states):
            st = "运行中"
        elif up:
            st = "部分异常"
        else:
            st = "异常"
        clusters.append({"name": r.get("name"), "type": r.get("type") or "MySQL",
                         "time": r.get("time") or "-", "nodes": states,
                         "up": up, "total": len(states), "status": st,
                         "checked": r.get("checked") or ""})
    installed = {}
    for label, keys in HA_TYPES:
        installed[label] = [
            {"name": a.get("name"), "type": a.get("type"),
             "host": a.get("host") or "127.0.0.1", "port": a.get("port") or "",
             "online": _probe(a.get("host") or "127.0.0.1", a.get("port") or 3306)}
            for a in apps if (a.get("type") or "").lower() in keys]
    return {"ok": True, "types": [t[0] for t in HA_TYPES],
            "clusters": clusters, "installed": installed}


