    @app.get("/assets/svg/<path:filename>")
    def assets_svg(filename):
        return send_from_directory(os.path.join(os.path.dirname(__file__), "static", "svg"), filename)

    @app.post("/api/agent/report")
    def api_report():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        if "host" not in d: return jsonify({"error":"need host"}), 400
        try:
            return jsonify(report(d["host"], d.get("ip",""), d.get("inet",""), d))
        except Exception as e:
            return jsonify({"error": str(e)}), 500

    @app.get("/api/agents")
    def api_agents():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """智能体列表。"""
        return jsonify({"list": _col("agents")})

    @app.post("/api/agents")
    def api_agents_add():
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        d.setdefault("typ", "Archetype"); d.setdefault("sev", "ok"); d.setdefault("status", "正常")
        d["time"] = time.strftime("%Y-%m-%d %H:%M:%S")
        return jsonify(col_add("agents", d))

    @app.post("/api/agents/<name>/rm")
    def api_agents_rm(name):
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        return jsonify(col_rm("agents", "name", name))

    @app.post("/api/agents/<name>/edit")
    def api_agents_edit(name):
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        rows = _col("agents")
        for r in rows:
            if r.get("name") == name:
                if d.get("name") and d["name"] != name and any(x.get("name") == d["name"] for x in rows):
                    return jsonify({"error": "same name exists"}), 400
                for k, v in d.items():
                    if v is not None: r[k] = v
                r["time"] = time.strftime("%Y-%m-%d %H:%M:%S")
                _save_col("agents", rows)
                _audit("info", "admin", f"编辑智能体 [{name}]", source="agents", operate="edit", detail_en=f"Edit agent [{name}]")
                return jsonify(r)
        return jsonify({"error": "not found"}), 404

    @app.post("/api/models/probe")
    def api_models_probe():
        """请求供应商 /models 接口(创建/编辑抽屉的「获取模型」)。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
