    @app.post("/api/models/verify")
    def api_models_verify():
        """验证模型账号: 请求 /models，结果存储 data/models.json 的 verified 字段。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        name = (d.get("name") or "").strip()
        rows = _col("models")
        hit = [r for r in rows if r.get("name") == name]
        if not hit: return jsonify({"ok": False, "msg": "模型账号不存在"})
        res = _models_probe(hit[0])
        hit[0]["verified"] = "验证成功" if res.get("ok") else "验证失败"
        hit[0]["verify_msg"] = (res.get("msg") or "")[:200]
        hit[0]["verify_time"] = time.strftime("%Y-%m-%d %H:%M:%S")
        if res.get("models"):
            hit[0]["pool"] = res["models"][:500]
        _save_col("models", rows)
        _op_log("model", "edit", detail_zh="验证模型账号 [%s] %s" % (name, hit[0]["verified"]),
                message=hit[0]["verify_msg"])
        return jsonify({"ok": bool(res.get("ok")), "msg": res.get("msg"),
                        "verified": hit[0]["verified"], "models": res.get("models") or []})

    @app.get("/api/local-models")
    def api_local_models():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """本地模型: 探测本地 ollama/vllm 及已加载模型。
        空环境返回空列表, 前端渲染"暂无数据 / 未检测到本地推理服务"。"""
        out = []
        try:
            r = _sp.run(["bash", "-lc", "command -v ollama && ollama list 2>/dev/null"],
                        capture_output=True, text=True, timeout=15)
            if not r.returncode:
                for ln in r.stdout.splitlines():
                    p = ln.split()
                    if len(p) >= 4 and p[0] != "NAME":
                        out.append({"name": p[0], "size": p[-3] + " " + p[-2], "modified": p[-1], "vendor": "ollama"})
        except Exception:
            pass
        try:
            r = _sp.run(["bash", "-lc", "command -v vllm && vllm --version 2>/dev/null | head -1"],
                        capture_output=True, text=True, timeout=15)
            if not r.returncode and r.stdout.strip():
                out.append({"name": "vllm", "size": "", "modified": "", "vendor": "vllm",
                            "ver": r.stdout.strip()})
        except Exception:
            pass
        return jsonify({"list": out})

    @app.get("/api/tamper/sites")
    def api_tamper_sites():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """网站防篡改「保护/排除模版」作用对象: 列出本站已部署网站目录。
        openresty = 是否检测到 OpenResty(专业版未安装时整页只有安装引导空态);
        模版记录来自 data/tamper.json, 总防护/今日防护按创建时间真实统计。"""
        sites = sites_list().get("sites", [])
        tpls = _col("tamper")
        today = time.strftime("%Y-%m-%d")
        out = []
        for s in sites:
            name = s.get("name") or ""
            mine = [t for t in tpls if t.get("site") == name]
            out.append({"name": name, "dir": "/www/wwwroot/" + name,
                        "type": "nginx" if s.get("type") in ("nginx", None) else "static",
                        "status": s.get("tamper", "未保护"),
                        "total": len(mine) + (1 if s.get("tamper") == "保护中" else 0),
                        "today": len([t for t in mine if (t.get("time") or "").startswith(today)])})
        return jsonify({"list": out, "openresty": _openresty_ok(), "templates": tpls})

    def _openresty_ok():
        try:
            if os.path.exists("/usr/local/openresty"): return True
            r = _sp.run(["docker", "ps", "--format", "{{.Image}} {{.Names}}"],
                        capture_output=True, text=True, timeout=6)
            return "openresty" in (r.stdout or "").lower()
        except Exception:
            return False

    @app.post("/api/tamper/tpl")
    def api_tamper_tpl():
        """新增/删除防篡改模版(保护模版/排除模版/不刷新目录), 存储 data/tamper.json。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        if d.get("op") == "rm":
            return jsonify(col_rm("tamper", "name", d.get("name")))
        path = (d.get("path") or "").strip()
        site = (d.get("site") or "").strip()
        kind = d.get("kind") or "保护模版"
        if not path: return jsonify({"ok": False, "error": "path required"})
        return jsonify(col_add("tamper", {"name": path, "site": site, "kind": kind,
                                          "path": path, "note": d.get("note") or "",
                                          "time": time.strftime("%Y-%m-%d %H:%M:%S")}))

    @app.post("/api/tamper/protect")
    def api_tamper_protect():
        """为指定网站启用/关闭防篡改(写 site.json 记录)。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        name = d.get("name"); on = bool(d.get("on"))
        f = os.path.join(SITES_DIR, name, "site.json")
        if not os.path.exists(f): return jsonify({"error": "site not found"}), 404
        rec = json.load(open(f)); rec["tamper"] = "保护中" if on else "未保护"
        json.dump(rec, open(f, "w"), ensure_ascii=False, indent=2)
        _audit("info", "admin", f"{'开启' if on else '关闭'}防篡改 [{name}]", source="tampers", operate="edit", detail_en=f"{'Enable' if on else 'Disable'} tamper [{name}]")
        return jsonify({"ok": True, "name": name, "status": rec["tamper"]})

