    @app.post("/api/mcp/test")   # MCP 连接测试: 按 SSE 地址探测
    def api_mcp_test():
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        url = (d.get("url") or "").strip()
        if not url: return jsonify({"ok": False, "msg": "地址为空"})
        u = urllib.parse.urlparse(url if "://" in url else "http://" + url)
        host = u.hostname
        port = u.port or (443 if u.scheme == "https" else 80)
        if not host: return jsonify({"ok": False, "msg": "地址格式错误"})
        try:
            s = socket.create_connection((host, port), timeout=3)
            s.close()
        except Exception as e:
            return jsonify({"ok": False, "msg": f"{host}:{port} 不可达 ({e.__class__.__name__})"})
        try:
            from urllib.request import Request as _Req, urlopen as _urlopen
            req = _Req(url, headers={"Accept": "text/event-stream"})
            with _urlopen(req, timeout=3) as r:
                return jsonify({"ok": True, "msg": f"HTTP {r.status} {host}:{port}"})
        except Exception as e:
            code = getattr(e, "code", None)
            if code: return jsonify({"ok": True, "msg": f"HTTP {code} {host}:{port}"})
            return jsonify({"ok": True, "msg": f"端口可达 {host}:{port} ({e.__class__.__name__})"})

