    def _cpu_pct_recent():
        try:
            parts = open("/proc/stat").readline().split()
            t1 = sum(int(v) for v in parts[1:]); i1 = int(parts[4])
            time.sleep(0.25)
            parts = open("/proc/stat").readline().split()
            t2 = sum(int(v) for v in parts[1:]); i2 = int(parts[4])
            return [round(100 * (1 - (i2 - i1) / max(1, t2 - t1)), 1)]
        except Exception:
            return [0]

    def _mem_pct_recent():
        try:
            mi = {}
            for l in open("/proc/meminfo"):
                if l.startswith("MemTotal") or l.startswith("MemAvailable"):
                    p = l.split(); mi[p[0].rstrip(":")] = int(p[1]) * 1024
            tot = mi.get("MemTotal", 0)
            return [round(100 * (1 - mi.get("MemAvailable", 0) / max(1, tot)), 1)]
        except Exception:
            return [0]

    @app.post("/api/mon/export")   # 导出监控数据为 CSV 文本返回 (可按时间范围)
    def api_mon_export():
        d = request.get_json(silent=True) or {}
        try:
            start = int(d.get("start") or 0); end = int(d.get("end") or 0)
        except (TypeError, ValueError):
            start = end = 0
        hist = _mon_history()
        if start or end:
            e = end or int(time.time()) + 60
            s = start or (e - 86400)
            hist = [x for x in hist if s <= x.get("ts", 0) <= e]
        if not hist:
            hist = [{"ts": int(time.time()), "cpu": _cpu_pct_recent()[0], "mem": _mem_pct_recent()[0],
                     "load": [0, 0, 0], "disk": {}, "net": {}}]
        def _busy2(v):
            try: return isinstance(v, (list, tuple)) and (v[0] or v[1])
            except Exception: return False
        devs = sorted({d for x in hist for d, v in (x.get("disk") or {}).items() if _busy2(v)})
        nics = sorted({n for x in hist for n, v in (x.get("net") or {}).items() if _busy2(v)})
        head = ["ts", "time", "load1", "load5", "load15", "cpu%", "mem%"]
        head += [f"disk_{x}_readKB" for x in devs] + [f"disk_{x}_writeKB" for x in devs]
        head += [f"net_{x}_rxKB" for x in nics] + [f"net_{x}_txKB" for x in nics]
        lines = [",".join(head)]
        for x in hist:
            l = x.get("load") or [0, 0, 0]
            row = [x.get("ts"), time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(x.get("ts", 0))),
                   l[0], l[1], l[2], x.get("cpu"), x.get("mem")]
            row += [(x.get("disk") or {}).get(k, [0, 0])[0] for k in devs]
            row += [(x.get("disk") or {}).get(k, [0, 0])[1] for k in devs]
            row += [(x.get("net") or {}).get(k, [0, 0])[0] for k in nics]
            row += [(x.get("net") or {}).get(k, [0, 0])[1] for k in nics]
            lines.append(",".join(str(v) for v in row))
        csv = "\n".join(lines)
        fname = f"monitor-{time.strftime('%Y%m%d%H%M%S')}.csv"
        if d.get("download"):
            return Response(csv, mimetype="text/csv",
                            headers={"Content-Disposition": f"attachment; filename={fname}"})
        return jsonify({"ok": True, "csv": csv, "file": fname, "rows": len(hist)})


