    # ---------- GPU 监控: 真实 nvidia-smi / rocm-smi 探测 + 历史采样 ----------
    GPU_HIST_FILE = DATA + "/gpu_hist.json"

    def _gpu_probe():
        """探测本地 GPU。返回 {"list":[...]} 或 {"error": "no gpu"}，绝不伪造。"""
        try:
            r = _sp.run(["bash", "-lc", "command -v nvidia-smi >/dev/null 2>&1 && nvidia-smi --query-gpu=name,temperature.gpu,utilization.gpu,memory.used,memory.total,bus_id --format=csv,noheader,nounits 2>/dev/null || (command -v rocm-smi >/dev/null 2>&1 && rocm-smi --showuse --showtemp --showmeminfo vram 2>/dev/null) || echo __NONE__"],
                        capture_output=True, text=True, timeout=15)
            txt = r.stdout.strip()
            if not txt or "__NONE__" in txt:
                return {"error": "no gpu", "reason": "未找到 nvidia-smi / rocm-smi"}
            out = []
            for line in txt.splitlines():
                p = [x.strip() for x in line.replace("%", "").split(",")]
                if len(p) >= 6:
                    out.append({"name": p[0], "temp": p[1], "util": p[2],
                                "mem": "%s/%s MiB" % (p[3], p[4]), "bus": p[5]})
            if not out:
                return {"error": "no gpu", "reason": "管理指令无输出"}
            return {"list": out}
        except Exception as e:
            return {"error": "no gpu", "reason": str(e)[:160]}

    def _gpu_hist_add(devs):
        rows = _load_json(GPU_HIST_FILE, [])
        t = time.strftime("%Y-%m-%d %H:%M:%S")
        for g in devs:
            rows.append({"time": t, "name": g.get("name"), "temp": g.get("temp"),
                         "util": g.get("util"), "mem": g.get("mem"), "bus": g.get("bus")})
        _save_json(GPU_HIST_FILE, rows[-5000:])

