    @app.get("/api/waf/records")
    def api_waf_records():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """WAF 拦截记录: 解析 nginx 日志中 4xx/5xx 行 + 常见攻击特征串。"""
        data = _nginx_log_lines()
        rows = []
        for l in data:
            m = re.search(r'(\S+)\s+[-\s]+\S+\s+' r'\[([^\]]+)\]' r'\s+"([^"]+)"\s+(\d{3})', l)
            if m:
                ip, ts, reqline, code = m.group(1), m.group(2), m.group(3), m.group(4)
                if code.startswith(("4", "5")):
                    rows.append({"ip": ip, "time": ts, "req": reqline, "code": code,
                                 "rule": "触发访问拦截" if reqline and ("SELECT" in reqline or "union" in reqline.lower() or "script" in reqline.lower()) else "状态码拦截"})
        rows = rows[-80:][::-1]
        return jsonify({"records": rows, "total": len(rows)})

    @app.get("/api/waf/blocks")
    def api_waf_blocks():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """WAF 封锁记录: 4xx/5xx 日志聚合 + 面板手动黑名单; 已解除(ignore)的不再出现。"""
        cfg = _waf_cfg()
        ign = set(cfg.get("ignore") or [])
        data = _nginx_log_lines()
        from collections import Counter
        bad = []
        sample = {}
        for l in data:
            m = re.search(r'(\S+)\s+[-\s]+\S+\s+' r'\[([^\]]+)\]' r'\s+"([^"]+)"\s+(\d{3})', l)
            if m and m.group(4).startswith(("4", "5")) and m.group(1) not in ign:
                bad.append(m.group(1))
                sample.setdefault(m.group(1), m.group(3))
        cnt = Counter(bad)
        rows = [{"ip": ip, "count": n, "time": "近 30 分钟", "reason": "多次异常请求自动封锁",
                 "src": "日志", "path": sample.get(ip, "/")}
                for ip, n in cnt.most_common(40)]
        have = {r["ip"] for r in rows}
        for x in cfg.get("lists") or []:
            if x.get("type") == "黑名单" and x.get("value") and x["value"] not in have:
                rows.insert(0, {"ip": x["value"], "count": 0, "time": x.get("time") or "-",
                                "reason": "手动加入黑名单", "src": "面板"})
        return jsonify({"blocks": rows, "total": len(rows)})

    @app.get("/api/waf/lists")
    def api_waf_lists():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """黑白名单: 从 nginx 配置 + 防火墙规则聚合真实白/黑名单项。"""
        w, sh = [], []
        try:
            for f in ["/etc/nginx/nginx.conf", "/etc/nginx/conf.d/*.conf", "/etc/nginx/sites-enabled/*"]:
                import glob
                for p in glob.glob(f):
                    txt = open(p, encoding="utf-8", errors="replace").read()
                    for line in txt.splitlines():
                        s = line.strip()
                        if s.startswith("allow ") and s.split()[-1] not in ("all",):
                            w.append({"type": "白名单", "value": s.split()[1], "rule": s, "src": "nginx"})
                        elif s.startswith("deny "):
                            sh.append({"type": "黑名单", "value": s.split()[1], "rule": s, "src": "nginx"})
        except Exception:
            pass
        mine = [{"type": x.get("type") or "黑名单", "value": x.get("value") or "",
                 "rule": x.get("rule") or "手动添加", "src": "面板", "time": x.get("time") or ""}
                for x in (_waf_cfg().get("lists") or []) if x.get("value")]
        rows = (mine + w + sh)[:60]
        return jsonify({"list": rows, "total": len(rows)})

