    @app.post("/api/waf/settings")
    def api_waf_settings_save():
        """op 分发: global{...} / site+on / list{...} / list_rm / unblock, 存储 data/waf.json。"""
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        cfg = _waf_cfg()
        if isinstance(d.get("global"), dict):
            for k in ("enabled", "sqli", "xss", "crawler", "cc"):
                if k in d["global"]: cfg["global"][k] = bool(d["global"][k])
            _audit("info", "admin", "WAF 全局设置: " + ", ".join(f"{k}={v}" for k, v in d["global"].items()),
                   source="waf", operate="edit", detail_en="Update WAF global settings")
        if d.get("site"):
            name = str(d["site"])
            f = os.path.join(SITES_DIR, name, "site.json")
            if not os.path.exists(f): return jsonify({"ok": False, "error": "site not found"})
            rec = json.load(open(f, encoding="utf-8"))
            rec["waf"] = "已防护" if d.get("on") else "未防护"
            json.dump(rec, open(f, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
            _audit("info", "admin", f"{'开启' if d.get('on') else '关闭'} WAF [{name}]",
                   source="waf", operate="edit", detail_en=f"{'Enable' if d.get('on') else 'Disable'} WAF [{name}]")
        if isinstance(d.get("list"), dict):
            it = d["list"]; v = (it.get("value") or "").strip()
            if not v: return jsonify({"ok": False, "error": "IP/网段必填"})
            cfg["lists"] = [x for x in (cfg.get("lists") or []) if x.get("value") != v]
            cfg["lists"].append({"type": it.get("type") or "黑名单", "value": v,
                                 "rule": (it.get("rule") or "").strip() or "手动添加",
                                 "time": time.strftime("%Y-%m-%d %H:%M:%S")})
            cfg["ignore"] = [x for x in (cfg.get("ignore") or []) if x != v]
            _audit("info", "admin", f"WAF {it.get('type') or '黑名单'} 添加 [{v}]",
                   source="waf", operate="create", detail_en=f"Add WAF list [{v}]")
        if d.get("list_rm"):
            v = str(d["list_rm"])
            cfg["lists"] = [x for x in (cfg.get("lists") or []) if x.get("value") != v]
            _audit("info", "admin", f"WAF 名单移除 [{v}]", source="waf", operate="delete",
                   detail_en=f"Remove WAF list [{v}]")
        if d.get("unblock"):
            ip = str(d["unblock"]).strip()
            cfg["lists"] = [x for x in (cfg.get("lists") or []) if x.get("value") != ip]
            ign = [x for x in (cfg.get("ignore") or []) if x != ip]
            ign.append(ip)
            cfg["ignore"] = ign[-500:]
            _audit("info", "admin", f"WAF 解除封锁 [{ip}]", source="waf", operate="edit",
                   detail_en=f"Unblock [{ip}]")
        _waf_save(cfg)
        return jsonify({"ok": True, "global": cfg["global"]})

