    @app.post("/api/kvm/pool")
    def api_kvm_pool():
        """存储池: 新建 / 启动 / 停止 / 删除。真实调用 virsh, 失败原因原样回显。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        op = d.get("op") or "add"
        name = (d.get("name") or "").strip()
        tgt = (d.get("target") or "").strip()
        if op == "add":
            if not name: return jsonify({"ok": False, "error": "name required"})
            tgt = tgt or (_kvm_image_dir() + "/" + name)
            try:
                os.makedirs(tgt, exist_ok=True)
            except Exception as e:
                return jsonify({"ok": False, "error": "无法创建目录 %s: %s" % (tgt, e)})
            rc, out = _kvm_run(["pool-define-as", name, "dir", "--target", tgt])
            if rc != 0: return jsonify({"ok": False, "error": out})
            _kvm_run(["pool-build", name])
            rc, out = _kvm_run(["pool-start", name])
            if rc != 0: return jsonify({"ok": False, "error": out})
            _op_log("vms", "create", "admin", detail_zh=f"创建存储池 [{name}]", message=tgt)
            return jsonify({"ok": True, "out": out})
        if not name: return jsonify({"ok": False, "error": "name required"})
        if op == "start":
            rc, out = _kvm_run(["pool-start", name])
        elif op == "stop":
            rc, out = _kvm_run(["pool-destroy", name])
        elif op in ("rm", "delete"):
            _kvm_run(["pool-destroy", name])
            rc, out = _kvm_run(["pool-undefine", name])
        else:
            return jsonify({"ok": False, "error": "bad op"})
        if rc != 0: return jsonify({"ok": False, "error": out})
        _op_log("vms", "create" if op == "start" else "delete", "admin",
                detail_zh=f"存储池 {name} {op}", message=out[:200])
        return jsonify({"ok": True, "out": out})

    @app.post("/api/kvm/net")
    def api_kvm_net():
        """虚拟网络: 建立 NAT 网络 / 启动 / 停止 / 删除。真实调用 virsh, 权限不足如实回显。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        op = d.get("op") or "add"
        name = (d.get("name") or "").strip()
        cidr = (d.get("cidr") or "").strip() or "10.0.122.1/24"
        auto = ("--autostart" if d.get("autostart") else None)
        if op == "add":
            if not name: return jsonify({"ok": False, "error": "name required"})
            gw, _, mask = cidr.partition("/")
            xml = ("<network><name>%s</name><forward mode='nat'/><bridge name='%s' stp='on' delay='0'/>"
                   "<ip address='%s' netmask='%s'/></network>") % (name, name + "0", gw, _kvm_mask(mask))
            rc, out = _kvm_run(["net-define", "/dev/stdin"], stdin=xml)
            if rc != 0: return jsonify({"ok": False, "error": out})
            rc, out = _kvm_run(["net-start", name])
            if rc != 0: return jsonify({"ok": False, "error": out})
            if auto: _kvm_run(["net-autostart", name])
            _op_log("vms", "create", "admin", detail_zh=f"创建虚拟网络 [{name}]", message=cidr)
            return jsonify({"ok": True, "out": out})
        if not name: return jsonify({"ok": False, "error": "name required"})
        if op == "start":
            rc, out = _kvm_run(["net-start", name])
        elif op == "stop":
            rc, out = _kvm_run(["net-destroy", name])
        elif op in ("rm", "delete"):
            _kvm_run(["net-destroy", name])
            rc, out = _kvm_run(["net-undefine", name])
        else:
            return jsonify({"ok": False, "error": "bad op"})
        if rc != 0: return jsonify({"ok": False, "error": out})
        _op_log("vms", "create" if op == "start" else "delete", "admin",
                detail_zh=f"虚拟网络 {name} {op}", message=out[:200])
        return jsonify({"ok": True, "out": out})

    @app.post("/api/kvm/image")
    def api_kvm_image():
        """镜像: 上传到默认镜像目录(写盘) / 删除。用于新建虚拟机时选择。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
