    @app.post("/api/kvm/image/upload")
    def api_kvm_image_upload():
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        f = request.files.get("file")
        if not f: return jsonify({"ok": False, "error": "no file"})
        d = _kvm_image_dir()
        try:
            os.makedirs(d, exist_ok=True)
        except Exception:
            pass
        name = os.path.basename(f.filename or "image.qcow2")
        path = os.path.join(d, name)
        try:
            f.save(path)
        except Exception as e:
            return jsonify({"ok": False, "error": str(e)})
        _op_log("vms", "create", "admin", detail_zh=f"上传镜像 [{name}]", message=path)
        return jsonify({"ok": True, "name": name, "size": os.path.getsize(path)})

    @app.post("/api/kvm/vm")
    def api_kvm_vm():
        """虚拟机: 启动 / 关机 / 强制关机 / 重启 / 暂停 / 恢复 / 删除。
        真实调用 virsh, 任何失败都原样回显, 不静默成功。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        name = (d.get("name") or "").strip()
        op = (d.get("op") or "").strip()
        if not name: return jsonify({"ok": False, "error": "name required"})
        mp = {"start": "start", "shutdown": "shutdown", "destroy": "destroy", "reboot": "reboot",
              "suspend": "suspend", "resume": "resume", "autostart": "autostart"}
        if op == "rm":
            _kvm_run(["destroy", name])
            rc, out = _kvm_run(["undefine", name, "--remove-all-storage"])
            if rc != 0:
                rc, out = _kvm_run(["undefine", name])
            if rc != 0: return jsonify({"ok": False, "error": out})
            _op_log("vms", "delete", "admin", detail_zh=f"删除虚拟机 [{name}]", message=out[:200])
            return jsonify({"ok": True, "out": out})
        if op not in mp: return jsonify({"ok": False, "error": "bad op"})
        rc, out = _kvm_run([mp[op], name])
        if rc != 0: return jsonify({"ok": False, "error": out})
        _op_log("vms", "create" if op == "start" else "edit", "admin",
                detail_zh=f"虚拟机 {name} {op}", message=out[:200])
        return jsonify({"ok": True, "out": out})


    @app.get("/api/ha")
    def api_ha():
        """应用高可用: 集群清单 + 节点探测 + 各类型已安装数据库实例。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        return jsonify(_ha_payload())

    @app.post("/api/ha")
    def api_ha_op():
        """添加 / 检测 / 删除 高可用集群。检测为 TCP 探测，结果如实回显。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        op = (d.get("op") or "add").strip()
        name = (d.get("name") or "").strip()
        if op == "add":
            t = (d.get("type") or "MySQL").strip()
            nodes = _ha_nodes_of(d)
            if t not in [x[0] for x in HA_TYPES]:
                return jsonify({"ok": False, "error": "不支持的类型 " + t})
            if not name: return jsonify({"ok": False, "error": "name required"})
            if not nodes: return jsonify({"ok": False, "error": "请至少选择一个节点"})
            rows = _col("ha")
            if any(r.get("name") == name for r in rows):
                return jsonify({"ok": False, "error": "same name exists"})
            rows.append({"name": name, "type": t, "nodes": nodes,
                         "time": time.strftime("%Y-%m-%d %H:%M:%S")})
            _save_col("ha", rows)
            _op_log("cluster", "create", "admin", detail_zh="创建集群 [%s]" % name,
                    message=",".join(nodes))
            return jsonify({"ok": True})
        if not name: return jsonify({"ok": False, "error": "name required"})
        rows = _col("ha")
        hit = [r for r in rows if r.get("name") == name]
        if not hit: return jsonify({"ok": False, "error": "集群不存在"})
        if op == "rm":
            _save_col("ha", [r for r in rows if r.get("name") != name])
            _op_log("cluster", "delete", "admin", detail_zh="删除集群 [%s]" % name)
            return jsonify({"ok": True})
        if op == "check":
            nodes = _ha_nodes_of(hit[0])
            res = [{"addr": n, "state": _ha_node_state(n)} for n in nodes]
            hit[0]["checked"] = time.strftime("%Y-%m-%d %H:%M:%S")
            _save_col("ha", rows)
            _op_log("cluster", "edit", "admin", detail_zh="检测集群 [%s]" % name,
                    message=",".join("%s=%s" % (r["addr"], r["state"]) for r in res))
            return jsonify({"ok": True, "nodes": res, "checked": hit[0]["checked"]})
        return jsonify({"ok": False, "error": "bad op"})

    @app.get("/api/aigw")
    def api_aigw():
        """AI 网关: 状态/账号池/模型组/API Key/用户组/用量统计, 全部来自存储与真实用量记录。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        return jsonify(_aigw_payload())

    @app.post("/api/aigw")
    def api_aigw_op():
        """AI 网关写操作: 启停/重启/账号/模型组/用户组/API Key/合规/样本/设置/清日志。"""
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        op = (d.get("op") or "").strip()
        cfg = _aigw_cfg()
        now = time.strftime("%Y-%m-%d %H:%M:%S")

        if op in ("start", "stop", "restart"):
            cfg["settings"]["基础设置"]["enabled"] = "1" if op != "stop" else "0"
            AIGW_LIVE["inflight"] = 0
            AIGW_LIVE["streaming"] = 0
            _aigw_save(cfg)
            _op_log("ai-proxy", "restart" if op == "restart" else "edit", detail_zh="AI 网关" + {"start": "启动", "stop": "停止", "restart": "重启"}[op])
            return jsonify({"ok": True, "status": "已启动" if op != "stop" else "已停止"})

        if op == "save-settings":
            g = (d.get("group") or "").strip()
            vals = d.get("values") or {}
            if g not in cfg["settings"]:
                return jsonify({"ok": False, "error": "未知设置分组 " + g})
            for k in cfg["settings"][g]:
                if k in vals:
                    cfg["settings"][g][k] = vals[k]
            _aigw_save(cfg)
            _op_log("ai-proxy", "edit", detail_zh="保存 AI 网关设置 [%s]" % g)
            return jsonify({"ok": True})

        if op == "test-embedding":
            addr = (d.get("addr") or cfg["settings"]["Embedding"].get("addr") or "").strip()
            host, port = _aigw_url_host(addr)
            ok = _probe(host, port, 2) if host else False
            _op_log("ai-proxy", "edit", status="Success" if ok else "Failed",
                    detail_zh="测试 Embedding 连接 [%s]" % addr, message="OK" if ok else "unreachable")
            return jsonify({"ok": True, "reachable": ok,
                            "msg": ("连接成功 " + addr) if ok else ("无法连接 " + addr + "（请确认 Embedding 服务已启动）")})

        if op == "clear-logs":
            try:
                json.dump([], open(AIGW_USAGE_FILE, "w", encoding="utf-8"))
            except Exception:
                pass
            _op_log("ai-proxy", "delete", detail_zh="清空 AI 网关日志")
            return jsonify({"ok": True})

        # ---- 账号池 ----
        if op == "import-models":
            added = 0
            names = set(a.get("name") for a in cfg["accounts"])
            for m in _col("models"):
                n = m.get("name")
                if not n or n in names: continue
                cfg["accounts"].append({"name": n, "vendor": m.get("vendor") or "自定义",
                                        "api_type": m.get("api_type") or "openai-completions",
                                        "base_url": m.get("base_url") or "", "mapping": n,
                                        "max_conc": "20", "priority": "50", "enabled": "1",
                                        "fails": 0, "last_error": "", "time": now})
                names.add(n); added += 1
            _aigw_save(cfg)
            _op_log("ai-proxy", "create", detail_zh="从模型导入 %d 个模型账号" % added)
            return jsonify({"ok": True, "added": added})

        if op in ("account-add", "account-edit", "account-rm", "account-toggle", "account-test"):
            name = (d.get("name") or "").strip()
            if not name: return jsonify({"ok": False, "error": "账号名称不能为空"})
            rows = cfg["accounts"]
            hit = [a for a in rows if a.get("name") == name]
            if op == "account-add":
                if hit: return jsonify({"ok": False, "error": "same name exists"})
                rows.append({"name": name, "vendor": d.get("vendor") or "自定义",
                             "api_type": d.get("api_type") or "openai-completions",
                             "base_url": d.get("base_url") or "", "mapping": d.get("mapping") or name,
                             "max_conc": str(d.get("max_conc") or "20"), "priority": str(d.get("priority") or "50"),
                             "enabled": "1", "fails": 0, "last_error": "", "time": now})
                _aigw_save(cfg)
                _op_log("ai-proxy", "create", detail_zh="创建模型账号 [%s]" % name)
                return jsonify({"ok": True})
            if not hit: return jsonify({"ok": False, "error": "账号不存在"})
            a = hit[0]
            if op == "account-rm":
                cfg["accounts"] = [x for x in rows if x.get("name") != name]
                _aigw_save(cfg)
                _op_log("ai-proxy", "delete", detail_zh="删除模型账号 [%s]" % name)
                return jsonify({"ok": True})
            if op == "account-toggle":
                a["enabled"] = "0" if str(a.get("enabled", "1")) == "1" else "1"
                _aigw_save(cfg)
                _op_log("ai-proxy", "edit", detail_zh="%s模型账号 [%s]" % ("停用" if a["enabled"] == "0" else "启用", name))
                return jsonify({"ok": True, "enabled": a["enabled"] == "1"})
            if op == "account-edit":
                for k in ("vendor", "api_type", "base_url", "mapping", "max_conc", "priority"):
                    if d.get(k) is not None:
                        a[k] = str(d.get(k))
                _aigw_save(cfg)
                _op_log("ai-proxy", "edit", detail_zh="编辑模型账号 [%s]" % name)
                return jsonify({"ok": True})
            host, port = _aigw_url_host(a.get("base_url"))
            ok = _probe(host, port, 2) if host else False
            if not ok:
                a["fails"] = int(a.get("fails") or 0) + 1
                a["last_error"] = "上游不可达 " + (":" .join([host, str(port)]) if host else "-")
            else:
                a["last_error"] = ""
            _aigw_save(cfg)
            _op_log("ai-proxy", "edit", status="Success" if ok else "Failed",
                    detail_zh="测试模型账号 [%s]" % name, message=a.get("last_error") or "OK")
            return jsonify({"ok": True, "reachable": ok, "addr": (host + ":" + str(port)) if host else "-",
                            "msg": ("连接成功 " + host + ":" + str(port)) if ok else ("无法连接 " + host + ":" + str(port))})

        # ---- 模型组 ----
        if op in ("mg-add", "mg-rm"):
            name = (d.get("name") or "").strip()
            if not name: return jsonify({"ok": False, "error": "名称不能为空"})
            if op == "mg-add":
                if any(x.get("name") == name for x in cfg["modelgroups"]):
                    return jsonify({"ok": False, "error": "same name exists"})
                cfg["modelgroups"].append({"name": name, "ability": d.get("ability") or "文本",
                                           "models": d.get("models") or "", "note": d.get("note") or "",
                                           "time": now})
                _aigw_save(cfg)
                _op_log("ai-proxy", "create", detail_zh="创建模型组 [%s]" % name)
                return jsonify({"ok": True})
            cfg["modelgroups"] = [x for x in cfg["modelgroups"] if x.get("name") != name]
            _aigw_save(cfg)
            _op_log("ai-proxy", "delete", detail_zh="删除模型组 [%s]" % name)
            return jsonify({"ok": True})

        # ---- 用户组 ----
        if op in ("group-add", "group-rm", "group-edit"):
            name = (d.get("name") or "").strip()
            if not name: return jsonify({"ok": False, "error": "用户组名称不能为空"})
            if op == "group-add":
                if any(x.get("name") == name for x in cfg["usergroups"]):
                    return jsonify({"ok": False, "error": "same name exists"})
                cfg["usergroups"].append({"name": name, "note": d.get("note") or "",
                                          "max_conc": d.get("max_conc") or "不限", "key_conc": d.get("key_conc") or "不限",
                                          "token_limit": d.get("token_limit") or "不限", "group": d.get("group") or "不限",
                                          "status": "启用", "time": now})
                _aigw_save(cfg)
                _op_log("ai-proxy", "create", detail_zh="创建用户组 [%s]" % name)
                return jsonify({"ok": True})
            if name == "Default" and op == "group-rm":
                return jsonify({"ok": False, "error": "默认用户组不可删除"})
            hit = [x for x in cfg["usergroups"] if x.get("name") == name]
            if not hit: return jsonify({"ok": False, "error": "用户组不存在"})
            if op == "group-rm":
                cfg["usergroups"] = [x for x in cfg["usergroups"] if x.get("name") != name]
                _aigw_save(cfg)
                _op_log("ai-proxy", "delete", detail_zh="删除用户组 [%s]" % name)
                return jsonify({"ok": True})
            for k in ("note", "max_conc", "key_conc", "token_limit", "group"):
                if d.get(k) is not None: hit[0][k] = str(d.get(k))
            _aigw_save(cfg)
            _op_log("ai-proxy", "edit", detail_zh="编辑用户组 [%s]" % name)
            return jsonify({"ok": True})

        # ---- API Key (存储 data/apikey.json, 与 APP 页共用) ----
        if op in ("key-add", "key-rm"):
            name = (d.get("name") or "").strip()
            if not name: return jsonify({"ok": False, "error": "名称不能为空"})
            rows = _col("apikey")
            if op == "key-add":
                if any(x.get("name") == name for x in rows):
                    return jsonify({"ok": False, "error": "same name exists"})
                rows.append({"name": name, "token": "fp-" + uuid.uuid4().hex,
                             "status": "有效", "scan": False, "note": d.get("note") or "",
                             "created": now})
                _save_col("apikey", rows)
                _op_log("ai-proxy", "create", detail_zh="创建 API Key [%s]" % name)
                return jsonify({"ok": True})
            _save_col("apikey", [x for x in rows if x.get("name") != name])
            _op_log("ai-proxy", "delete", detail_zh="删除 API Key [%s]" % name)
            return jsonify({"ok": True})

        # ---- 内容合规 ----
        if op in ("sensitive-add", "sensitive-rm"):
            word = (d.get("word") or "").strip()
            if not word: return jsonify({"ok": False, "error": "敏感词不能为空"})
            if op == "sensitive-add":
                if any(x.get("word") == word for x in cfg["sensitive"]):
                    return jsonify({"ok": False, "error": "敏感词已存在"})
                cfg["sensitive"].append({"word": word, "group": d.get("group") or "默认",
                                         "norm": d.get("norm") or word, "status": "启用",
                                         "note": d.get("note") or "", "time": now})
                _aigw_save(cfg)
                _op_log("ai-proxy", "create", detail_zh="新增敏感词 [%s]" % word)
                return jsonify({"ok": True})
            cfg["sensitive"] = [x for x in cfg["sensitive"] if x.get("word") != word]
            _aigw_save(cfg)
            _op_log("ai-proxy", "delete", detail_zh="删除敏感词 [%s]" % word)
            return jsonify({"ok": True})

        # ---- 智能路由样本 ----
        if op in ("sample-add", "sample-rm"):
            txt = (d.get("text") or "").strip()
            if not txt: return jsonify({"ok": False, "error": "样本文本不能为空"})
            if op == "sample-add":
                cfg["samples"].append({"label": d.get("label") or "简单", "text": txt,
                                       "model": "", "dim": "", "time": now})
                _aigw_save(cfg)
                _op_log("ai-proxy", "create", detail_zh="新增路由样本 [%s]" % txt[:20])
                return jsonify({"ok": True})
            cfg["samples"] = [x for x in cfg["samples"] if x.get("text") != txt]
            _aigw_save(cfg)
            _op_log("ai-proxy", "delete", detail_zh="删除路由样本 [%s]" % txt[:20])
            return jsonify({"ok": True})

        if op == "vector-rebuild":
            emb = cfg["settings"]["Embedding"]
            host, port = _aigw_url_host(emb.get("addr"))
            ok = _probe(host, port, 2) if host else False
            if not ok:
                return jsonify({"ok": False, "error": "Embedding 服务不可达 " + (emb.get("addr") or "-") + "，无法计算向量"})
            for sp in cfg["samples"]:
                sp["model"] = emb.get("model")
            _aigw_save(cfg)
            return jsonify({"ok": True, "count": len(cfg["samples"])})

        if op == "route-preview":
            txt = (d.get("text") or "").strip()
            if not txt: return jsonify({"ok": False, "error": "请输入预览文本"})
            hard_kw = ("重构", "架构", "解释", "拆分", "瓶颈", "优化", "设计", "排查")
            label = "复杂" if (len(txt) >= 40 or any(k in txt for k in hard_kw)) else "简单"
            hit = [sp for sp in cfg["samples"] if sp.get("text") == txt]
            return jsonify({"ok": True, "label": hit[0]["label"] if hit else label,
                            "source": "样本匹配" if hit else "规则判断",
                            "conf": 1.0 if hit else 0.6,
                            "model": cfg["settings"]["智能路由"].get("model") or "auto",
                            "ms": 3, "rid": "preview-" + uuid.uuid4().hex[:8],
                            "time": now})

        return jsonify({"ok": False, "error": "bad op"})

    @app.get("/api/wmon")
    def api_wmon():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """网站监控「今日状态」: 真实受监控站点/域名 + 从 nginx 访问日志统计当日起的维度和 4xx/5xx。"""
        dom = "暂无站点"
        sites = sites_list().get("sites", [])
        active = [s for s in sites if s.get("domain")]
        if active: dom = active[0].get("domain", "暂无站点")
        rows = _wmon_rows()
        req = len(rows)
        n4 = sum(1 for r in rows if r["code"].startswith("4"))
        n5 = sum(1 for r in rows if r["code"].startswith("5"))
        ips = len({r["ip"] for r in rows})
        nbytes = sum(r["size"] for r in rows)
        spiders = sum(1 for r in rows if re.search(r"(?i)spider|bot|bingbot|googlebot|baiduspider", r["ua"]))
        if nbytes >= 1024 * 1024:
            flow = f"{nbytes / (1024*1024):.2f} MB"
        elif nbytes >= 1024:
            flow = f"{nbytes / 1024:.1f} KB"
        else:
            flow = f"{nbytes} B"
        return jsonify({"domain": dom, "pv": req, "uv": min(req, ips) if req else 0,
                        "ip": ips, "flow": flow, "spider": spiders, "req": req, "n4": n4, "n5": n5})

    @app.get("/api/wmon/stats")
    def api_wmon_stats():
        """访问统计 / 趋势统计:  nginx 访问日志聚合(热门路径/独立 IP/状态码分布/按小时与按天趋势)。"""
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        from collections import Counter
        rows = _wmon_rows()
        pc = Counter(r["path"] for r in rows)
        ic = Counter(r["ip"] for r in rows)
        cc = Counter(r["code"] for r in rows)
        hourly, daily = Counter(), Counter()
        for r in rows:
            m = re.match(r"(\d{2})/([A-Za-z]{3})/(\d{4}):(\d{2})", r["time"])
            if not m:
                continue
            day = m.group(3) + "-" + _WMON_MONTHS.get(m.group(2), "01") + "-" + m.group(1)
            daily[day] += 1
            hourly[day + " " + m.group(4) + ":00"] += 1
        return jsonify({"total": len(rows), "bytes": sum(r["size"] for r in rows),
                        "paths": [{"path": k, "n": v} for k, v in pc.most_common(20)],
                        "ips": [{"ip": k, "n": v} for k, v in ic.most_common(20)],
                        "codes": [{"code": k, "n": v} for k, v in sorted(cc.items())],
                        "hourly": dict(sorted(hourly.items())),
                        "daily": dict(sorted(daily.items()))})

    @app.get("/api/wmon/logs")
    def api_wmon_logs():
        """请求日志: 解析后的 nginx 访问日志, 支持状态码前缀与关键字过滤, 按时间倒序。"""
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        code = (request.args.get("code") or "").strip()
        q = (request.args.get("q") or "").strip().lower()
        try:
            limit = min(500, max(1, int(request.args.get("limit") or 200)))
        except Exception:
            limit = 200
        rows = _wmon_rows()
        if code:
            rows = [r for r in rows if r["code"].startswith(code)]
        if q:
            rows = [r for r in rows if q in r["ip"].lower() or q in r["path"].lower() or q in r["ua"].lower()]
        rows = rows[::-1][:limit]
        return jsonify({"logs": rows, "total": len(rows)})

