    PS_FILE = os.path.join(DATA, "panel_settings.json")
    SNAP_DIR = os.path.join(DATA, "snapshots")
    _PANEL_START = time.time()
    PANEL_VERSION = "v2.4.2"
    PS_DEFAULT = {"theme": "light", "primary": "#005eeb", "menuTabs": "Disable", "watermark": "Disable",
                  "lang": "中文(简体)", "timeout": 86400, "accessAddr": "", "proxy": "",
                  "hiddenMenu": [], "region": "跟随运行区域（默认）", "backupAccts": [],
                  "license": "", "licenseTime": "",
                  "port": 8890, "entrance": "", "sessionTimeout": 86400, "allowIPs": "",
                  "twoFactor": "Disable"}

    def _ps_read():
        out = json.loads(json.dumps(PS_DEFAULT))
        try:
            j = json.load(open(PS_FILE))
            if isinstance(j, dict): out.update(j)
        except Exception:
            pass
        return out

    def _ps():
        out = _ps_read()
        try: out["alias"] = _load_app_cfg().get("alias", "")
        except Exception: out["alias"] = ""
        return out

    def _ps_write(d):
        cur = _ps_read()
        for k, v in (d or {}).items():
            if k in PS_DEFAULT: cur[k] = v
        json.dump(cur, open(PS_FILE, "w"), ensure_ascii=False, indent=2)
        return cur

