    @app.post("/api/skills/install")
    def api_skill_install():
        """两种入库方式: ① 上传 SKILL.md 内容 ② 从本地已有路径导入。均存储。"""
        if not _can_write(request.headers): return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(force=True, silent=True) or {}
        rows = _skills_rows()
        src_path = os.path.expanduser(str(d.get("path") or ""))
        content = d.get("content") or ""

        if src_path and not content:
            if not os.path.isfile(src_path):
                return jsonify({"ok": False, "error": "文件不存在: %s" % src_path})
            pn, pdesc = _skill_parse_md(src_path)
            n = pn
            desc = d.get("desc") or pdesc
            src = d.get("src") or "导入"
            store_path = src_path
        elif content:
            n = (d.get("name") or "").strip()
            if not n:
                return jsonify({"ok": False, "error": "名称必填"})
            desc = d.get("desc", "")
            src = d.get("src") or "上传"
            tgt = os.path.join(SKILLS_DIR, n)
            try:
                os.makedirs(tgt, exist_ok=True)
                store_path = os.path.join(tgt, "SKILL.md")
                with open(store_path, "w", encoding="utf-8") as fh:
                    fh.write(content)
            except Exception as e:
                return jsonify({"ok": False, "error": "写入失败: %s" % e})
        else:
            n = (d.get("name") or "").strip()
            if not n:
                return jsonify({"ok": False, "error": "名称必填"})
            desc = d.get("desc", "")
            src = d.get("src") or "自定义"
            store_path = ""

        if any(r0.get("name") == n for r0 in rows):
            return jsonify({"ok": False, "error": "同名 Skill 已存在: %s" % n})
        rec = {"name": n, "desc": desc, "version": d.get("version") or "1.0.0",
               "src": src, "enabled": True, "risk": d.get("risk") or "低",
               "path": store_path, "updated": time.strftime("%Y-%m-%d")}
        rows.append(rec); _save_col("skills", rows)
        _audit("info", "admin", "安装 [%s]" % n, source="skills-hub", operate="create",
               detail_en="Install [%s]" % n)
        return jsonify({"ok": True, "item": rec})

