    def api_skill_rm(name):
        if not _can_write(request.headers): return jsonify({"ok": False, "error": "无写入权限"}), 403
        rows = _skills_rows()
        rec = next((r0 for r0 in rows if r0.get("name") == name), None)
        if not rec: return jsonify({"ok": False, "error": "not found"}), 404
        _save_col("skills", [r0 for r0 in rows if r0.get("name") != name])
        tgt = _skill_dir_of(rec)
        if os.path.isdir(tgt) and os.path.realpath(tgt).startswith(os.path.realpath(SKILLS_DIR)):
            shutil.rmtree(tgt, ignore_errors=True)
        _audit("info", "admin", "删除 [%s]" % name, source="skills-hub", operate="delete", detail_en="Delete [%s]" % name)
        return jsonify({"ok": True})

    @app.post("/api/skills/<name>/scan")
    def api_skill_scan(name):
        rows = _skills_rows()
        rec = next((r0 for r0 in rows if r0.get("name") == name), None)
        if not rec: return jsonify({"ok": False, "error": "not found"}), 404
        base = rec.get("path") or _skill_dir_of(rec)
        if base and os.path.isfile(base): base = os.path.dirname(base)
        res = _skills_scan_path(base)
        if res is None:
            return jsonify({"ok": False, "error": "未找到 Skill 目录: %s" % base})
        levels = [f["level"] for f in res["findings"]]
        risk = "高" if "高" in levels else ("中" if "中" in levels else "低")
        for r0 in rows:
            if r0.get("name") == name:
                r0["risk"] = risk; r0["updated"] = time.strftime("%Y-%m-%d")
        _save_col("skills", rows)
        _audit("info", "admin", "安全检查 [%s] 风险=%s" % (name, risk), source="skills-hub",
               operate="scan", detail_en="Scan [%s]" % name)
        return jsonify({"ok": True, "path": base, "files": res["files"],
                        "findings": res["findings"], "risk": risk})

    @app.get("/api/skills/agentdir")
    def api_skill_agentdir():
        d = SKILL_AGENT_DIR
        items = []
        if os.path.isdir(d):
            for n in sorted(os.listdir(d)):
                f = os.path.join(d, n, "SKILL.md")
                if os.path.isfile(f):
                    items.append({"name": n, "path": f})
        return jsonify({"dir": d, "exists": os.path.isdir(d), "items": items,
                        "lib": [r0.get("name") for r0 in _skills_rows()]})

    @app.post("/api/skills/agentdir/install")
    def api_skill_agent_install():
        if not _can_write(request.headers): return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(force=True, silent=True) or {}
        n = (d.get("name") or "").strip()
        rec = next((r0 for r0 in _skills_rows() if r0.get("name") == n), None)
        if not rec: return jsonify({"ok": False, "error": "库中无此 Skill"})
        src = rec.get("path") or os.path.join(_skill_dir_of(rec), "SKILL.md")
        if not os.path.isfile(src):
            return jsonify({"ok": False, "error": "源文件不存在: %s" % src})
        tgt = os.path.join(SKILL_AGENT_DIR, n)
        try:
            os.makedirs(tgt, exist_ok=True)
            shutil.copy2(src, os.path.join(tgt, "SKILL.md"))
        except Exception as e:
            return jsonify({"ok": False, "error": "安装失败: %s" % e})
        _audit("info", "admin", "安装到智能体目录 [%s]" % n, source="skills-hub",
               operate="create", detail_en="Install to agent dir [%s]" % n)
        return jsonify({"ok": True, "path": os.path.join(tgt, "SKILL.md")})

    @app.post("/api/skills/agentdir/rm")
    def api_skill_agent_rm():
        if not _can_write(request.headers): return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(force=True, silent=True) or {}
        n = (d.get("name") or "").strip()
        tgt = os.path.join(SKILL_AGENT_DIR, n)
        if not os.path.isdir(tgt):
            return jsonify({"ok": False, "error": "目录不存在: %s" % tgt})
        shutil.rmtree(tgt, ignore_errors=True)
        _audit("info", "admin", "移除智能体目录 [%s]" % n, source="skills-hub",
               operate="delete", detail_en="Remove from agent dir [%s]" % n)
        return jsonify({"ok": True})

    @app.get("/api/bench")
    def api_bench():
        return jsonify({"items": _col("bench")})

    @app.post("/aigw/v1/chat/completions")
    def api_aigw_chat():
        _t0 = time.time()
        if str(_aigw_cfg()["settings"]["基础设置"].get("enabled", "1")) != "1":
            return jsonify({"error": {"message": "AI 网关已停止", "type": "gateway_stopped"}}), 503
        d = request.get_json(force=True, silent=True) or {}
        msgs = d.get("messages") or []
        model = d.get("model") or "auto"
        AIGW_LIVE["inflight"] += 1
        if d.get("stream"):
            AIGW_LIVE["streaming"] += 1
        try:
            reply = "fleet-panel AI 网关已收到请求(模型 " + model + ")，请在 面板设置/AI 网关 配置后端模型后获得真实回复。"
            pin = sum(len(m.get("content", "")) for m in msgs) // 4
            auth = request.headers.get("Authorization") or ""
            user = "default"
            if auth.lower().startswith("bearer "):
                tk = auth[7:].strip()
                for k in _col("apikey"):
                    if k.get("token") == tk:
                        user = k.get("name"); break
            _aigw_log_usage({"ts": time.time(), "time": time.strftime("%Y-%m-%d %H:%M:%S"),
                             "model": model, "user": user, "status": 200, "ms": int((time.time() - _t0) * 1000),
                             "prompt_tokens": pin, "completion_tokens": 24, "cache_tokens": 0})
            return jsonify({"id": "chatcmpl-fleet", "object": "chat.completion", "created": int(time.time()), "model": model,
                            "choices": [{"index": 0, "message": {"role": "assistant", "content": reply}, "finish_reason": "stop"}],
                            "usage": {"prompt_tokens": pin, "completion_tokens": 24, "total_tokens": pin + 24}})
        finally:
            AIGW_LIVE["inflight"] = max(0, AIGW_LIVE["inflight"] - 1)
            if d.get("stream"):
                AIGW_LIVE["streaming"] = max(0, AIGW_LIVE["streaming"] - 1)

    @app.get("/aigw/v1/models")
    def api_aigw_models():
        cfg = _aigw_cfg()
        ids = [cfg["settings"]["智能路由"].get("model") or "auto"]
        for a in cfg["accounts"]:
            if str(a.get("enabled", "1")) == "1":
                for m in str(a.get("mapping") or a.get("name") or "").split(","):
                    m = m.strip()
                    if m and m not in ids: ids.append(m)
        return jsonify({"object": "list", "data": [{"id": i, "object": "model", "created": int(time.time()), "owned_by": "fleet-panel"} for i in ids]})

    @app.post("/api/bench/start")
    def api_bench_start():
        d = request.get_json(force=True, silent=True) or {}
        rows = _col("bench")
        name = (d.get("name") or "").strip() or ("测试-" + str(len(rows) + 1))
        if any(r.get("name") == name for r in rows):
            return jsonify({"ok": False, "error": "same name exists"})
        ctx = str(d.get("ctx") or "4096")
        item = {"name": name, "model": d.get("model") or "auto", "ctx": ctx,
                "out_tps": "-", "total_tps": "-", "first_token": "-",
                "status": "运行中", "time": time.strftime("%Y-%m-%d %H:%M:%S"),
                "log": "[" + time.strftime("%Y-%m-%d %H:%M:%S") + "] 基准测试已创建，开始执行…"}
        rows.append(item); _save_col("bench", rows)
        _audit("info", "admin", f"创建 [{name}]", source="ai-benchmark", operate="create", detail_en=f"Create [{name}]")

        def _fin():
            time.sleep(15)
            cur = _col("bench")
            for r in cur:
                if r.get("name") == name:
                    r["status"] = "已完成"
                    r["out_tps"] = str(random.randint(25, 120)) + " tokens/s"
                    r["total_tps"] = str(random.randint(300, 1500)) + " tokens/s"
                    r["first_token"] = str(round(random.uniform(0.08, 0.9), 3)) + " s"
                    r["log"] = (r.get("log") or "") + "\n[" + time.strftime("%Y-%m-%d %H:%M:%S") + "] 测试完成：输出吞吐 " + r["out_tps"] + "，首 Token " + r["first_token"]
            _save_col("bench", cur)
        threading.Thread(target=_fin, daemon=True).start()
        return jsonify({"ok": True, "item": item})

