    @app.post("/api/ops/report/settings")
    def api_ops_report_settings_set():
        if not _can_write(request.headers): return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        cur = _report_settings()
        for k in ("default_days", "mid", "high"):
            if k in d:
                try: cur[k] = max(1, int(d[k]))
                except Exception: pass
        if cur["high"] < cur["mid"]: cur["high"] = cur["mid"]
        try: json.dump(cur, open(REPORT_SETTINGS, "w"), ensure_ascii=False, indent=1)
        except Exception: pass
        if d.get("keep"):
            msf = os.path.join(DATA, "mon_settings.json")
            try: ms = json.load(open(msf))
            except Exception: ms = {}
            try: ms["keep"] = max(1, int(d["keep"]))
            except Exception: ms["keep"] = 7
            try: json.dump(ms, open(msf, "w"), ensure_ascii=False)
            except Exception: pass
            try: MON_COLLECT["keep"] = ms["keep"]
            except Exception: pass
            cur["keep"] = ms.get("keep", 7)
        return jsonify({"ok": True, "settings": cur})

