    @app.post("/api/users/auth/sync")
    def api_users_auth_sync():
        """真实 LDAP 同步：按 basedn+filter 拉取用户并存储为本地账号。"""
        if not _can_write(request.headers): return jsonify({"error":"forbidden"}), 403
        d = auth_load(); srv = (d.get("server") or "").strip()
        if not srv: return jsonify({"ok": False, "error": "请先填写服务端地址"})
        try: import ldap3
        except Exception: return jsonify({"ok": False, "error": "服务端未安装 ldap3 模块"})
        try:
            s = ldap3.Server(srv, get_info=ldap3.NONE, connect_timeout=max(1, int(d.get("timeout", 10))))
            c = ldap3.Connection(s, user=(d.get("binddn") or None), password=(d.get("bindpwd") or None), auto_bind=True)
            attr = "uid"
            try: attr = (json.loads(d.get("mapping") or "{}") or {}).get("name", "uid")
            except Exception: pass
            flt = (d.get("filter") or "(uid=%(user)s)").replace("%(user)s", "*")
            c.search(d.get("basedn") or "", flt,
                     attributes=[attr], paged_size=int(d.get("pageSize", 1000)))
            names = []
            for e in c.entries:
                v = e[attr].value if attr in e else None
                if isinstance(v, list): v = v[0] if v else None
                if v: names.append(str(v))
            c.unbind()
            u = _load_users(); added = 0
            for n in names:
                if n in u: continue
                u[n] = {"pwd": uuid.uuid4().hex[:16], "role": d.get("role", "viewer"),
                        "source": "AD/LDAP", "desc": "由 LDAP 同步导入"}; added += 1
            _save_users(u)
            d = auth_save({"sync": {"enable": d.get("sync", {}).get("enable", False),
                                    "cron": d.get("sync", {}).get("cron", ""),
                                    "last": time.strftime("%Y-%m-%d %H:%M:%S"),
                                    "count": added},
                           "records": ([{"time": time.strftime("%Y-%m-%d %H:%M:%S"), "found": len(names),
                                         "added": added, "status": "Success"}] + (d.get("records") or []))[:50]})
            return jsonify({"ok": True, "found": len(names), "added": added})
        except Exception as e:
            d = auth_save({"records": ([{"time": time.strftime("%Y-%m-%d %H:%M:%S"), "found": 0,
                                         "added": 0, "status": "Failed", "msg": str(e)[:160]}] + (d.get("records") or []))[:50]})
            return jsonify({"ok": False, "error": str(e)[:200]})

