    @app.post("/api/sites/<name>/settings")
    def api_site_settings(name):
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        f = os.path.join(SITES_DIR, name, "site.json")
        if not os.path.exists(f): return jsonify({"ok": False, "error": "no site"}), 404
        rec = json.load(open(f))
        for k in ("type","domain","upstream","https","ssl_enabled","ssl_cert","waf_enabled","waf_rules","group","remark"):
            if k in d: rec[k] = d[k]
        json.dump(rec, open(f,"w"), ensure_ascii=False, indent=2)
        # 重生成站点配置文件(停用状态不落 conf, 保持下线)
        conf_path = os.path.join(SITES_DIR, name, "site.conf")
        if rec.get("enabled", True):
            with open(conf_path, "w") as fh: fh.write(nginx_conf(rec))
        elif os.path.exists(conf_path):
            os.remove(conf_path)
        _reload_nginx()
        log_event("sites", "info", f"site {name} 设置更新: {d.keys()}")
        return jsonify({"ok": True, "site": rec})

