        d = request.get_json(force=True, silent=True) or {}
        r = site_create(d.get("name",""), d.get("type",""),
                        d.get("domain",""), d.get("upstream",""))
        if r.get("ok") and (d.get("group") or d.get("remark")):
            f = os.path.join(SITES_DIR, d.get("name",""), "site.json")
            try:
                rec = json.load(open(f))
                if d.get("group"): rec["group"] = d["group"]
                if d.get("remark"): rec["remark"] = d["remark"]
                json.dump(rec, open(f,"w"), ensure_ascii=False)
                r["site"] = rec
            except Exception:
                pass
        return jsonify(r)

