    @app.post("/api/sites/groups")
    def api_site_group_add():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        name = (d.get("name") or "").strip()
        if not name: return jsonify({"ok": False, "error": "分组名不能为空"}), 400
        gs = site_groups_list()
        if name in gs: return jsonify({"ok": False, "error": "分组已存在"}), 400
