    @app.post("/api/app/alias")
    def api_app_alias():
        who = _can_write(request.headers)
        if not who: return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        alias = (d.get("alias") or "").strip()
        if len(alias) > 128: return jsonify({"ok": False, "error": "别名长度不能超过 128"})
        cfg = _load_app_cfg(); old = cfg.get("alias", "")
        cfg["alias"] = alias; _save_app_cfg(cfg)
        _audit("info", who, f"修改面板别名 [{old}] -> [{alias}]", source="xapp", operate="edit", detail_en=f"Update app alias to [{alias}]")
        return jsonify({"ok": True, "alias": alias})

    @app.post("/api/app/keys")
    def api_app_key_new():
        who = _can_write(request.headers)
        if not who: return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        name = (d.get("name") or "").strip()
        if not name: return jsonify({"ok": False, "error": "名称必填"})
        token = "fp-" + uuid.uuid4().hex
        rec = {"name": name, "token": token, "status": "有效", "scan": False,
               "created": time.strftime("%Y-%m-%d %H:%M:%S")}
        r = col_add("apikey", rec)
        if not r.get("ok"): return jsonify(r)
        return jsonify({"ok": True, "item": rec})

    @app.post("/api/app/keys/<name>/scan")
    def api_app_key_scan(name):
        who = _can_write(request.headers)
        if not who: return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        on = bool(d.get("on"))
        rows = _col("apikey")
        hit = next((r for r in rows if r.get("name") == name), None)
        if not hit: return jsonify({"ok": False, "error": "no key"})
        hit["scan"] = on; _save_col("apikey", rows)
        _audit("info", who, f"{'开启' if on else '关闭'}扫码绑定 [{name}]", source="xapp",
               operate="edit", detail_en=f"{'Enable' if on else 'Disable'} QR binding [{name}]")
        return jsonify({"ok": True, "scan": on})

    @app.post("/api/app/bind")
    def api_app_bind():
        who = _can_write(request.headers)
        if not who: return jsonify({"error": "forbidden"}), 403
        d = request.get_json(force=True, silent=True) or {}
        name = (d.get("name") or "").strip()
        rows = _col("apikey")
        hit = next((r for r in rows if r.get("name") == name), None)
        if not hit: return jsonify({"ok": False, "error": "Key 不存在"})
        if hit.get("status") != "有效": return jsonify({"ok": False, "error": "Key 已失效"})
        if not hit.get("scan"): return jsonify({"ok": False, "error": "该 Key 未开启扫码绑定"})
        cfg = _load_app_cfg(); cfg["key"] = name
        cfg["bindings"] = (cfg.get("bindings") or []) + [{
            "key": name, "device": (request.headers.get("User-Agent") or "")[:120],
            "time": time.strftime("%Y-%m-%d %H:%M:%S")}]
        _save_app_cfg(cfg)
        _audit("info", who, f"绑定 API Key [{name}]", source="xapp", operate="edit", detail_en=f"Bind API key [{name}]")
        return jsonify({"ok": True, "key": name})

    @app.post("/api/app/unbind")
    def api_app_unbind():
        who = _can_write(request.headers)
        if not who: return jsonify({"error": "forbidden"}), 403
        cfg = _load_app_cfg(); old = cfg.get("key", ""); cfg["key"] = ""
        _save_app_cfg(cfg)
        _audit("info", who, f"解绑 API Key [{old}]", source="xapp", operate="edit", detail_en=f"Unbind API key [{old}]")
        return jsonify({"ok": True})

    @app.get("/api/app/qr")
    def api_app_qr():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        cfg = _load_app_cfg()
        name = (request.args.get("key") or cfg.get("key") or "").strip()
        row = next((r for r in _col("apikey") if r.get("name") == name), None)
        if not row: return jsonify({"ok": False, "error": "请先绑定有效的 Key"}), 400
        token = row.get("token") or ""
        payload = "fleetapp://bind?host=%s&alias=%s&key=%s" % (
            request.host, urllib.parse.quote(cfg.get("alias") or ""), token)
        try:
            import qrcode, qrcode.image.svg
            img = qrcode.make(payload, image_factory=qrcode.image.svg.SvgPathImage, box_size=10, border=2)
            buf = io.BytesIO(); img.save(buf)
            svg = buf.getvalue().decode("utf-8")
        except Exception as e:
            return jsonify({"ok": False, "error": "二维码生成失败: %s" % e}), 500
        return jsonify({"ok": True, "payload": payload, "alias": cfg.get("alias") or "",
                        "svg": svg})

