    # ---- SSL & 证书 (F) ----
    ACMESH = os.path.expanduser("~/.acme.sh/acme.sh")
    os.makedirs(CERTS_DIR, exist_ok=True)

    # 证书附加信息(备注/自动续签/Acme账号) + Acme/DNS 账号库 + 自签证书, 均为面板本地持久
    CERT_META_FILE = DATA + "/cert_meta.json"
    CERT_ACCTS_FILE = DATA + "/cert_accts.json"

    def _cert_meta_all():
        try: return json.load(open(CERT_META_FILE))
        except Exception: return {}

    def _cert_meta(dom):
        return _cert_meta_all().get(dom, {})

    def _cert_meta_set(dom, patch):
        m = _cert_meta_all(); cur = m.get(dom, {}); cur.update(patch or {}); m[dom] = cur
        json.dump(m, open(CERT_META_FILE, "w"), ensure_ascii=False, indent=2)

    def _cert_meta_drop(dom):
        m = _cert_meta_all(); m.pop(dom, None)
        json.dump(m, open(CERT_META_FILE, "w"), ensure_ascii=False, indent=2)

    def _cert_accts():
        try: d = json.load(open(CERT_ACCTS_FILE))
        except Exception: d = {}
        d.setdefault("acme", []); d.setdefault("dns", [])
        return d

    def _cert_accts_save(d):
        json.dump(d, open(CERT_ACCTS_FILE, "w"), ensure_ascii=False, indent=2)

    def _acme_accounts_live():
        """从 ~/.acme.sh/ca 目录读取真实已注册的 ACME 账户"""
        out = []
        base = os.path.expanduser("~/.acme.sh/ca")
        if not os.path.isdir(base): return out
        for srv in os.listdir(base):
            d = os.path.join(base, srv)
            aj = os.path.join(d, "directory", "account.json")
            if not os.path.exists(aj): continue
            try: info = json.load(open(aj))
            except Exception: info = {}
            email = ""
            cf = os.path.join(d, "directory", "account.conf")
            if os.path.exists(cf):
                mm = re.search(r"ACCOUNT_EMAIL='([^']*)'", open(cf).read())
                email = mm.group(1) if mm else ""
            out.append({"server": srv, "status": info.get("status", "valid"),
                        "created": (info.get("createdAt") or "")[:10], "email": email,
                        "key": "EC " + (info.get("key", {}).get("crv") or "")})
        return out

    def _load_certlist():
        out = []
        # ACME 申请来的证书 (acme.sh 目录) + 面板内上传/自签的证书 (CERTS_DIR/self/<dom>)
        roots = [(os.path.expanduser("~/.acme.sh"), "acme"),
                 (os.path.join(CERTS_DIR, "self"), "self")]
        for root, kind in roots:
            if not os.path.isdir(root): continue
            for nm in sorted(os.listdir(root)):
                if kind == "acme":
                    if not nm.endswith("_ecc"): continue
                    d = os.path.join(root, nm)
                    cf = os.path.join(d, nm[:-4] + ".conf")
                    if not os.path.exists(cf): continue
                    dom = nm[:-4]
                else:
                    d = os.path.join(root, nm)
                    if not os.path.isdir(d): continue
                    cf = os.path.join(d, nm + ".conf")
                    dom = nm
                rec = {"domain": dom, "kind": kind}
                try:
                    t = open(cf).read()
                    rec["alt"] = re.search(r"Le_Alt='([^']*)'", t) and re.search(r"Le_Alt='([^']*)'", t).group(1)
                    rec["webroot"] = re.search(r"Le_Webroot='([^']*)'", t) and re.search(r"Le_Webroot='([^']*)'", t).group(1)
                except Exception: pass
                cer = os.path.join(d, dom + ".cer")
                if os.path.exists(cer):
                    try:
                        o = _sp.run(["openssl","x509","-in",cer,"-noout","-dates","-enddate","-subject","-issuer","-serial"],capture_output=True,text=True)
                        rec["info"] = o.stdout.strip()
                        m = re.search(r"notAfter=(.*)", o.stdout)
                        rec["expires"] = m.group(1).strip() if m else "?"
                        mi = re.search(r"issuer=(.*)", o.stdout)
                        rec["issuer"] = mi.group(1).strip() if mi else ""
                        if os.path.exists(cf):
                            ren = re.search(r"Le_NextRenewTime='?(\d+)'?", open(cf).read())
                            if ren:
                                import datetime as _dt
                                rec["renew"] = _dt.datetime.fromtimestamp(int(ren.group(1))).strftime("%Y-%m-%d")
                    except Exception: rec["expires"]="?"
                if rec.get("alt") in (None, "", "no"): rec["alt"] = ""
                if rec.get("webroot") in (None, "", "no"): rec["webroot"] = ""
                mt = _cert_meta(dom)
                rec["remark"] = mt.get("remark", "")
                rec["autorenew"] = mt.get("autorenew", kind == "acme")
                rec["acct"] = mt.get("acct", "默认")
                rec["method"] = mt.get("method") or ("upload" if kind == "self" and mt.get("self") == "upload"
                                                     else "selfsign" if kind == "self"
                                                     else "dns_cf" if (rec.get("webroot") or "").startswith("dns") else "manual")
                if kind == "self" and mt.get("self") == "upload": rec["method"] = "upload"
                out.append(rec)
        out.sort(key=lambda r: r.get("domain",""))
        return out

    def _cert_issue(domain, alt=""):
        if not os.path.exists(ACMESH):
            return {"ok": False, "error": f"acme.sh 不存在: {ACMESH}"}
        args = [ACMESH, "--issue", "--dns", "dns_cf", "-d", domain]
        for a in alt.split(","):
            a = a.strip()
            if a: args += ["-d", a]
        args += ["--keylength", "ec-256", "--server", "letsencrypt"]
        env = dict(os.environ, HOME=os.path.expanduser("~"), CF_Token_Confirm="1")
        try:
            r = _sp.run(args, capture_output=True, text=True, timeout=300, env=env)
            cer = os.path.expanduser(f"~/.acme.sh/{domain}_ecc/{domain}.cer")
            star = os.path.exists(cer)
            # 非 0 退出也可能是"已存在且未到期, 跳过续期"(acme.sh exit 2), 此时证书仍可用, 不算失败
            has_valid = False
            if star:
                try:
                    out = _sp.run(["openssl","x509","-in",cer,"-dates","-noout"],
                                  capture_output=True, text=True, timeout=15).stdout
                    import time as _t
                    end = _t.strptime(out.split("notAfter=")[-1].split("\n")[0], "%b %d %H:%M:%S %Y %Z")
                    has_valid = _t.mktime(end) > _t.time()
                except Exception:
                    has_valid = True
            ok = (r.returncode == 0 or has_valid) and star
            msg = ("证书已签发/已就绪" if ok else "签发失败") + "\n" + (r.stdout + r.stderr)[-800:]
            if ok: log_event("cert", "ok", f"issue {domain} alt={alt or 'None'}")
            else: log_event("cert", "err", f"issue {domain}: {msg[:120]}")
            return {"ok": ok, "msg": msg}
        except Exception as e:
            log_event("cert", "err", f"issue {domain}: {e}")
            return {"ok": False, "error": str(e)}

    # 面板原生自动续签: 后台线程周期扫描, 到 ARI 续期窗就调 _cert_issue 续
    RENEW_CHECK_EVERY = 6*3600   # 每 6h 扫一次
    def _cert_due():
        """返回已到期/临近续期窗的域名列表 (读 acme.sh conf 的 Le_NextRenewTime/notAfter)"""
        due, now = [], int(time.time())
        for c in _load_certlist():
            dom = c.get("domain")
            src = os.path.expanduser(f"~/.acme.sh/{dom}_ecc")
            if not os.path.isdir(src): continue
            nr = None
            try:
                t = open(os.path.join(src, dom + ".conf")).read()
                nr = re.search(r"Le_NextRenewTime='?(\d+)'?", t)
                nr = int(nr.group(1)) if nr else None
            except Exception: nr = None
            if nr is not None and nr <= now: due.append(dom); continue
            # 无 Le_NextRenewTime 时回退: notAfter 距今 < 30 天视为需要续
            try:
                o = _sp.run(["openssl","x509","-in",os.path.join(src,dom+".cer"),
                             "-noout","-enddate"], capture_output=True, text=True, timeout=15).stdout
                m = re.search(r"notAfter=(.*)", o)
                if m:
                    import datetime as _dt
                    end = _dt.datetime.strptime(m.group(1).strip(), "%b %d %H:%M:%S %Y %Z").timestamp()
                    if end - now < 30*86400: due.append(dom)
            except Exception: pass
        return due

    def _cert_autorenew_worker():
        import threading as _th
        def loop():
            while True:
                try:
                    for dom in _cert_due():
                        if not _cert_meta(dom).get("autorenew", True): continue
                        r = _cert_issue(dom)
                        log_event("cert", "ok" if r.get("ok") else "err",
                                  f"auto-renew {dom}: {'ok' if r.get('ok') else r.get('msg','')[:60]}")
                except Exception as e:
                    log_event("cert", "err", f"auto-renew scan: {e}")
                time.sleep(RENEW_CHECK_EVERY)
        _th.Thread(target=loop, daemon=True).start()

    def _cert_deploy(domain):
        """把证书拷到 CERTS_DIR, 供站点/网关挂载。"""
        src = os.path.expanduser(f"~/.acme.sh/{domain}_ecc")
        if not os.path.isdir(src):
            src = os.path.join(CERTS_DIR, "self", domain)
        if not os.path.isdir(src): return {"ok": False, "error": "no cert dir"}
        dst = os.path.join(CERTS_DIR, domain)
        os.makedirs(dst, exist_ok=True)
        for f in ("fullchain.cer", domain + ".cer", domain + ".key", "ca.cer"):
            if os.path.exists(os.path.join(src, f)):
                _sp.run(["cp", os.path.join(src, f), os.path.join(dst, f)])
        log_event("cert", "info", f"deployed {domain} -> {dst}")
        return {"ok": True, "dir": dst}

    def _cert_logs(domain, limit=200):
        """证书操作日志: 取 events 表中 cert 来源的记录, 按域名过滤"""
        c = db()
        try:
            rows = c.execute("SELECT at,level,msg FROM events WHERE host='cert' ORDER BY at DESC LIMIT ?",
                             (limit,)).fetchall()
        except Exception:
            rows = []
        import datetime as _dt
        out = []
        for at, lv, msg in rows:
            if domain and domain not in (msg or ""): continue
            out.append({"time": _dt.datetime.fromtimestamp(at).strftime("%Y-%m-%d %H:%M:%S"),
                        "level": lv, "msg": msg})
        return out

    def _cert_selfsign(domain, days=3650, alt=""):
        """面板内自签证书 (openssl 生成, 存 CERTS_DIR/self/<domain>)"""
        dom = domain.strip()
        if not re.fullmatch(r"(\*\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}", dom):
            return {"ok": False, "error": "bad domain"}
        d = os.path.join(CERTS_DIR, "self", dom)
        os.makedirs(d, exist_ok=True)
        key, cer = os.path.join(d, dom + ".key"), os.path.join(d, dom + ".cer")
        san = ",".join(["DNS:" + dom] + ["DNS:" + x.strip() for x in (alt or "").split(",") if x.strip()])
        try:
            r = _sp.run(["openssl", "req", "-x509", "-nodes", "-newkey", "ec",
                         "-pkeyopt", "ec_paramgen_curve:prime256v1", "-days", str(days),
                         "-subj", "/CN=" + dom, "-addext", "subjectAltName=" + san,
                         "-keyout", key, "-out", cer],
                        capture_output=True, text=True, timeout=60)
            if r.returncode != 0:
                return {"ok": False, "error": (r.stderr or r.stdout)[-400:]}
            shutil.copyfile(cer, os.path.join(d, "fullchain.cer"))
            open(os.path.join(d, dom + ".conf"), "w").write(
                f"Le_Alt='{alt or ''}'\nLe_Webroot='selfsign'\n")
            _cert_meta_set(dom, {"self": "selfsign", "method": "selfsign",
                                 "autorenew": False, "alt": alt or ""})
            log_event("cert", "ok", f"self-sign {dom} ({days}d)")
            return {"ok": True, "dir": d}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def _cert_upload(domain, cert_pem, key_pem):
        """面板内上传证书 (用户粘贴 PEM), 存 CERTS_DIR/self/<domain>"""
        dom = domain.strip()
        if not re.fullmatch(r"(\*\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}", dom):
            return {"ok": False, "error": "bad domain"}
        if "BEGIN CERTIFICATE" not in (cert_pem or "") or "PRIVATE KEY" not in (key_pem or ""):
            return {"ok": False, "error": "证书或私钥格式不对(需 PEM)"}
        d = os.path.join(CERTS_DIR, "self", dom)
        os.makedirs(d, exist_ok=True)
        open(os.path.join(d, dom + ".cer"), "w").write(cert_pem.strip() + "\n")
        open(os.path.join(d, "fullchain.cer"), "w").write(cert_pem.strip() + "\n")
        kp = os.path.join(d, dom + ".key")
        open(kp, "w").write(key_pem.strip() + "\n"); os.chmod(kp, 0o600)
        try:
            o = _sp.run(["openssl", "x509", "-in", os.path.join(d, dom + ".cer"), "-noout", "-subject"],
                        capture_output=True, text=True, timeout=15).stdout
            if "CN" not in o: return {"ok": False, "error": "证书解析失败"}
        except Exception as e:
            return {"ok": False, "error": str(e)}
        open(os.path.join(d, dom + ".conf"), "w").write("Le_Alt=''\nLe_Webroot='upload'\n")
        _cert_meta_set(dom, {"self": "upload", "method": "upload", "autorenew": False})
        log_event("cert", "ok", f"upload {dom}")
        return {"ok": True, "dir": d}

    def _cert_rm(domain):
        dom = domain.strip().replace("..", "").replace("/", "")
        removed = []
        for p in (os.path.expanduser(f"~/.acme.sh/{dom}_ecc"), os.path.join(CERTS_DIR, "self", dom),
                  os.path.join(CERTS_DIR, dom)):
            if os.path.isdir(p):
                shutil.rmtree(p, ignore_errors=True); removed.append(p)
        _cert_meta_drop(dom)
        log_event("cert", "info", f"removed {dom}")
        return {"ok": True, "removed": removed}

    @app.get("/api/certs")
    def api_certs():
        return jsonify({"ok": True, "certs": _load_certlist()})

    @app.post("/api/certs/issue")
    def api_cert_issue():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        dom = d.get("domain","").strip()
        if not dom: return jsonify({"ok": False, "error": "need domain"}), 400
        # 基本校验: 只允许合法域名(防注入 acme.sh)
        if not re.fullmatch(r"(\*\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}", dom):
            return jsonify({"ok": False, "error": "bad domain"}), 400
        # 申请方式/Acme 账号/备注/自动续签 随签发一起落库
        _cert_meta_set(dom, {"remark": d.get("remark", ""), "acct": d.get("acct") or "默认",
                             "method": d.get("method") or "dns_cf",
                             "autorenew": bool(d.get("autorenew", True)),
                             "alt": d.get("alt", "")})
        return jsonify(_cert_issue(dom, d.get("alt","")))

    @app.post("/api/certs/selfsign")
    def api_cert_selfsign():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        return jsonify(_cert_selfsign(d.get("domain", ""), int(d.get("days") or 3650), d.get("alt", "")))

    @app.post("/api/certs/upload")
    def api_cert_upload():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        r = _cert_upload(d.get("domain", ""), d.get("cert", ""), d.get("key", ""))
        if r.get("ok"): _cert_meta_set(d.get("domain", "").strip(), {"remark": d.get("remark", "")})
        return jsonify(r)

    @app.post("/api/certs/<domain>/update")
    def api_cert_update(domain):
        """改备注 / 自动续签开关 / Acme 账号"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        patch = {}
        for k in ("remark", "autorenew", "acct", "method", "alt"):
            if k in d: patch[k] = d[k]
        _cert_meta_set(domain, patch)
        return jsonify({"ok": True})

    @app.post("/api/certs/<domain>/rm")
    def api_cert_rm(domain):
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        return jsonify(_cert_rm(domain))

    @app.get("/api/certs/logs")
    def api_cert_logs():
        return jsonify({"ok": True, "items": _cert_logs(request.args.get("domain", ""))})

    @app.get("/api/certs/acme-accounts")
    def api_cert_acme_accts():
        return jsonify({"ok": True, "items": _acme_accounts_live()})

    @app.get("/api/certs/dns-accounts")
    def api_cert_dns_accts():
        d = _cert_accts()
        live = []
        cf = os.path.expanduser("~/.acme.sh/account.conf")
        tok = ""
        if os.path.exists(cf):
            m = re.search(r"SAVED_CF_Token='([^']+)'", open(cf).read())
            tok = m.group(1) if m else ""
        if tok:
            live.append({"name": "Cloudflare(默认)", "type": "Cloudflare",
                         "token": tok[:10] + "…" + tok[-4:], "builtin": True})
        return jsonify({"ok": True, "items": live + d["dns"]})

    @app.post("/api/certs/dns-accounts")
    def api_cert_dns_add():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        nm = (d.get("name") or "").strip()
        if not nm: return jsonify({"ok": False, "error": "need name"}), 400
        box = _cert_accts()
        if any(x.get("name") == nm for x in box["dns"]):
            return jsonify({"ok": False, "error": "名称已存在"}), 400
        box["dns"].append({"name": nm, "type": d.get("type") or "Cloudflare",
                           "token": (d.get("token") or "")[:10] + "…", "builtin": False})
        _cert_accts_save(box)
        log_event("cert", "info", f"dns account add {nm}")
        return jsonify({"ok": True})

    @app.post("/api/certs/dns-accounts/rm")
    def api_cert_dns_rm():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        d = request.get_json(force=True, silent=True) or {}
        nm = (d.get("name") or "").strip()
        box = _cert_accts()
        if nm.startswith("Cloudflare(默认)") or any(x.get("name") == nm and x.get("builtin") for x in box["dns"]):
            return jsonify({"ok": False, "error": "内置账号不可删除"}), 400
        box["dns"] = [x for x in box["dns"] if x.get("name") != nm]
        _cert_accts_save(box)
        return jsonify({"ok": True})

    @app.post("/api/certs/<domain>/deploy")
    def api_cert_deploy(domain):
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not re.fullmatch(r"(\*\.)?[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}", domain):
            return jsonify({"ok": False, "error": "bad domain"}), 400
        return jsonify(_cert_deploy(domain))

    # ---- 高级功能:审计 / 进程 / 磁盘 / 防火墙 (H) ----
    def _ensure_log_tables():
        c = db()
        c.execute("""CREATE TABLE IF NOT EXISTS operation_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT, operate TEXT, user TEXT,
            node TEXT, status TEXT, detail_zh TEXT, detail_en TEXT, message TEXT, created_at TEXT)""")
        c.execute("""CREATE TABLE IF NOT EXISTS login_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT, ip TEXT, address TEXT, user TEXT,
            agent TEXT, status TEXT, message TEXT, created_at TEXT)""")
        c.commit()

    @app.post("/api/audit")
    def api_audit():
        """操作日志：{operation,page,pageSize,status,source,node} -> {items,total}（同 1Panel /core/logs/operation）"""
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        _ensure_log_tables()
        d = request.get_json(force=True, silent=True) or {}
        try: page = max(1, int(d.get("page") or 1))
        except Exception: page = 1
        try: size = max(1, min(1000, int(d.get("pageSize") or 20)))
        except Exception: size = 20
        where, args = [], []
        kw = (d.get("operation") or "").strip()
        if kw: where.append("(detail_zh LIKE ? OR detail_en LIKE ? OR operate LIKE ? OR user LIKE ?)"); args += ["%" + kw + "%"] * 4
        if d.get("source"): where.append("source = ?"); args.append(d["source"].replace("_", "-"))
        if d.get("status") and d["status"] != "All": where.append("status = ?"); args.append(d["status"])
        if d.get("node"): where.append("(node = ? OR (node IS NULL AND ? = 'local'))"); args += [d["node"], d["node"]]
        w = (" WHERE " + " AND ".join(where)) if where else ""
        c = db()
