    @app.post("/api/loginlog")
    def api_loginlog():
        """访问日志：{info,status,page,pageSize} -> {items,total}（同 1Panel /core/logs/login）"""
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        _ensure_log_tables()
        d = request.get_json(force=True, silent=True) or {}
        try: page = max(1, int(d.get("page") or 1))
        except Exception: page = 1
        try: size = max(1, min(1000, int(d.get("pageSize") or 20)))
        except Exception: size = 20
        where, args = [], []
        kw = (d.get("info") or "").strip()
        if kw:
            where.append("(ip LIKE ? OR address LIKE ? OR user LIKE ? OR agent LIKE ?)")
            args += ["%" + kw + "%"] * 4
        if d.get("status") and d["status"] != "All": where.append("status = ?"); args.append(d["status"])
        w = (" WHERE " + " AND ".join(where)) if where else ""
        try: port = int((d.get("port") if d.get("port") else _ssh_port()))
        except Exception: port = 22
        c = db()
        total = c.execute("SELECT COUNT(*) FROM login_logs" + w, args).fetchone()[0]
        rows = c.execute("SELECT ip,address,user,agent,status,message,created_at FROM login_logs" + w
                         + " ORDER BY id DESC LIMIT ? OFFSET ?", args + [size, (page - 1) * size]).fetchall()
        _port = port
        items = [{"ip": r[0], "address": r[1], "area": r[1] or "", "port": _port, "authMode": "password",
                  "user": r[2], "agent": (r[3] or "")[:80], "status": r[4],
                  "message": r[5] or "", "date": r[6]} for r in rows]
        return jsonify({"ok": True, "items": items, "total": total})

    def _ssh_port():
        try:
            for l in open("/etc/ssh/sshd_config"):
                ls = l.strip()
                if ls and not ls.startswith("#") and ls.lower().startswith("port"):
                    return int(ls.split()[1]); break
        except Exception: pass
        return 22

    @app.post("/api/loginlog/export")
    def api_loginlog_export():
        """SSH 登录日志导出（csv 附件，列 = 1Panel 导出列：地址/归属/端口/登录方式/用户/状态/时间）。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
