        if d.get("status") and d["status"] != "All": where.append("status = ?"); args.append(d["status"])
        try: lim = int(d.get("count") or 100)
        except Exception: lim = 100
        q = "SELECT ip,address,user,status,message,created_at FROM login_logs"
        if where: q += " WHERE " + " AND ".join(where)
        q += " ORDER BY id DESC" + ("" if lim in (-1, 0) else " LIMIT %d" % max(1, min(100000, lim)))
        port = _ssh_port()
