    _SYS_ANSI = re.compile(r"\x1b\[[0-9;]*[A-Za-z]")

    def _syslog_rows():
        """系统日志(主机日志)：面板事件 + systemd journal，字段对齐 1Panel /logs/host-system"""
        out = []
        try:
            since = open(os.path.join(DATA, "syslog_cleared.json")).read().strip()
            since = time.mktime(time.strptime(since, "%Y-%m-%d %H:%M:%S")) if since else 0
        except Exception:
            since = 0
        try:
            for host, level, msg, at in db().execute(
                    "SELECT host,level,msg,at FROM events WHERE at > ? ORDER BY at DESC LIMIT 200", (since,)).fetchall():
                out.append({"raw": "[%s] %s: %s" % (time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(at)), host, msg),
                            "service": "fleet-panel", "status": "Success" if level == "ok" else ("Failed" if level == "err" else level),
                            "priority": _hl_priority(level),
                            "time": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(at)),
                            "message": "%s: %s" % (host, msg), "duration": "-"})
        except Exception:
            pass
        out.extend(_journal_rows()[:800])
        out.sort(key=lambda r: str(r.get("time") or ""), reverse=True)
        return out[:1000]

    def _journal_rows():
        """从 journald（或 /var/log/syslog、messages）读取主机日志行
        {service, priority, time, message, hostname, identifier}"""
        recs = []
        try:
            res = _sp.run(["journalctl", "-o", "json", "--no-pager", "-n", "800"], capture_output=True, text=True, timeout=10)
            if res.returncode == 0 and res.stdout.strip():
                for ln in res.stdout.splitlines():
                    try:
                        j = json.loads(ln)
                    except Exception:
                        continue
                    msg = j.get("MESSAGE") or ""
                    if not isinstance(msg, str): msg = str(msg)
                    msg = _SYS_ANSI.sub("", msg).strip()
                    if not msg: continue
                    ident = j.get("_COMM") or j.get("SYSLOG_IDENTIFIER") or j.get("_SYSTEMD_UNIT") or ""
                    if j.get("SYSLOG_IDENTIFIER"): ident = j.get("SYSLOG_IDENTIFIER")
                    try:
                        pr = int(j.get("PRIORITY") or 6)
                    except Exception:
                        pr = 6
                    ts = j.get("__REALTIME_TIMESTAMP")
                    try:
                        at = int(int(ts) / 1000000) if ts else 0
                    except Exception:
                        at = 0
                    tm = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(at)) if at else ""
                    recs.append({"service": str(ident), "priority": str(max(0, min(7, pr))),
                                 "time": tm, "message": msg, "hostname": j.get("_HOSTNAME") or "",
                                 "raw": "%s %s %s[%s]: %s" % (tm, j.get("_HOSTNAME") or "", ident,
                                                              j.get("_PID") or "", msg)})
            elif res.returncode == 0:
                recs = []
        except Exception:
            recs = []
        if not recs:
            for f in ("/var/log/syslog", "/var/log/messages"):
                try:
                    lines = open(f, errors="replace").read().splitlines()[-800:]
                except Exception:
                    continue
                if not lines: continue
                for ln in lines:
                    ln = _SYS_ANSI.sub("", ln).strip()
                    if not ln or ln.startswith("~"): continue
                    m = re.match(r"^(\w{3}\s+\d+\s[\d:]+)\s+(\S+)\s+([^\[:]+)(?:\[\d+\])?:\s*(.*)$", ln)
                    if m:
                        tm, host, ident, msg = m.group(1), m.group(2), m.group(3).strip(), m.group(4)
                        try:
                            tm = time.strftime("%Y-%m-%d %H:%M:%S", time.strptime("%d %s" % (time.localtime().tm_year, tm), "%Y %b %d %H:%M:%S"))
                        except Exception:
                            pass
                    else:
                        tm, host, ident, msg = "", "", "syslog", ln
                    ct = re.search(r"\(([a-z]+)/([a-z]+)\)", msg) or re.search(r"\b(emerg|alert|crit|err|warn|notice|info|debug)\b", msg, re.I)
                    pr = {"emerg": "0", "alert": "1", "crit": "2", "err": "3", "warn": "4", "notice": "5", "info": "6", "debug": "7"}.get(
                        (ct.group(1) if ct else "info").lower(), "6")
                    msg = re.sub(r"^\S+\s+\S+\s+\S+\s+[^:]+:\s*", "", msg)
                    recs.append({"service": ident, "priority": pr, "time": tm, "message": msg, "hostname": host})
                break
        return recs

    @app.get("/api/logs")
    def api_logs_misc():
        """系统日志 / 任务日志（legacy /api/logs?type=system|task，供日志审计页的对应子页使用）"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        typ = request.args.get("type") or "system"
        kw = (request.args.get("kw") or "").strip()
        st = (request.args.get("status") or "").strip()
        try: page = max(1, int(request.args.get("page") or 1))
        except Exception: page = 1
        try: size = max(1, min(1000, int(request.args.get("pageSize") or 20)))
        except Exception: size = 20
        pri = (request.args.get("priority") or "").strip()
        if typ == "system":
            name = (request.args.get("file") or "").strip()
            agent = (request.args.get("agent") or "Agent").strip()
            if name:
                return jsonify({"ok": True, "content": _read_log_file(name), "name": name})
            rows = _syslog_rows() if agent != "Core" else []
            svc = (request.args.get("service") or "").strip()
            if svc: rows = [r for r in rows if (r.get("service") or "").lower() == svc.lower()]
            if kw: rows = [r for r in rows if kw in (r.get("service") or "") or kw in (r.get("message") or "")]
            if pri: rows = [r for r in rows if str(r.get("priority") or "") == pri]
            page_rows = rows[(page - 1) * size: page * size]
            return jsonify({"ok": True, "items": page_rows, "total": len(rows),
                            "hasMore": page * size < len(rows),
                            "services": sorted({r.get("service") or "" for r in _syslog_rows() if r.get("service")}),
                            "keywordFilterSupported": False})
        if typ == "host":
            rows = _syslog_rows()
            svc = (request.args.get("service") or "").strip()
            if svc: rows = [r for r in rows if (r.get("service") or "").lower() == svc.lower()]
            if kw: rows = [r for r in rows if kw in (r.get("message") or "") or kw in (r.get("service") or "")]
            if pri: rows = [r for r in rows if str(r.get("priority") or "") == pri]
            return jsonify({"ok": True, "items": rows[(page - 1) * size: page * size], "total": len(rows),
                            "services": sorted({r.get("service") or "" for r in _syslog_rows() if r.get("service")})})
        if typ == "task":
            try: rows = json.loads(open(os.path.join(DATA, "joblog.json")).read() or "[]")
            except Exception: rows = []
            if not isinstance(rows, list): rows = []
            for r in rows: r.pop("end", None)
            rows.reverse()
            if kw: rows = [r for r in rows if kw in (r.get("name") or "") or kw in (r.get("message") or "")]
            if st and st != "All": rows = [r for r in rows if (r.get("status") or "") == st]
            return jsonify({"ok": True, "items": rows[(page - 1) * size: page * size], "total": len(rows)})
        return jsonify({"ok": True, "items": [], "total": 0})

