    # ---- 主机日志（1Panel /logs/operation … /logs/website） ----
    def _hl_events():
        try:
            return db().execute("SELECT at,host,level,msg FROM events ORDER BY id DESC LIMIT 5000").fetchall()
        except Exception:
            return []

    def _hl_ts(v):
        v = (v or "").strip()
        if not v: return None
        try:
            if v.isdigit(): return int(v)
            v = v.replace("T", " ")[:19]
            return int(time.mktime(time.strptime(v, "%Y-%m-%d %H:%M:%S")))
        except Exception:
            return None

    def _hl_priority(level):
        return {"critical": "2", "crit": "2", "emerg": "0", "alert": "1", "error": "3", "err": "3",
                "warning": "4", "warn": "4", "notice": "5", "info": "6", "debug": "7"}.get((level or "").lower(), "6")

    @app.get("/api/logs/system/files")
    def api_logs_system_files():
        """系统日志文件列表（1Panel /logs/system/files）"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        names = []
        for d in ("/var/log",):
            try:
                for fn in os.listdir(d):
                    fp = os.path.join(d, fn)
                    if os.path.isfile(fp) and not fn.startswith(".") and fn != "btmp" and not fn.endswith(".gz"):
                        names.append(fn)
            except Exception:
                pass
        names.sort()
        return jsonify({"ok": True, "items": names})

    def _read_log_file(name, tail=500):
        name = os.path.basename(name or "syslog")
        path = os.path.join("/var/log", name)
        if not os.path.isfile(path):
            cmd = ["journalctl", "-t", name.replace(".log", ""), "-n", str(tail), "-o", "short-iso", "--no-pager"]
        else:
            cmd = ["tail", "-n", str(tail), path]
        try:
            r = _sp.run(cmd, capture_output=True, text=True, timeout=8)
            content = r.stdout or ""
        except Exception:
            content = ""
        if not content.strip() and name == "syslog":
            try:
                r = _sp.run(["journalctl", "-n", str(tail), "-o", "short-iso", "--no-pager"], capture_output=True, text=True, timeout=8)
                content = r.stdout or ""
            except Exception:
                content = ""
        content = re.sub(r"\x1b\[[0-9;]*[A-Za-z]", "", content)
        return content

    _HL_UNITS = {"running": None, "all": None, "at": 0.0}

    def _hl_units():
        """systemd 服务单元列表（缓存 60s）"""
        now = time.time()
        if _HL_UNITS["all"] is not None and now - _HL_UNITS["at"] < 60:
            return _HL_UNITS["running"], _HL_UNITS["all"]
        running, allu = [], []
        for args in (["--type=service"], ["--type=service", "--all"]):
            try:
                r = _sp.run(["systemctl", "list-units"] + args + ["--plain", "--no-legend", "--no-pager"],
                            capture_output=True, text=True, timeout=8)
                names = [ln.split()[0] for ln in (r.stdout or "").splitlines() if ln.strip()]
            except Exception:
                names = []
            if "--all" in args:
                allu = names
            else:
                running = names
        _HL_UNITS.update(running=running, all=allu, at=now)
        return running, allu

    def _hl_jver():
        try:
            r = _sp.run(["journalctl", "--version"], capture_output=True, text=True, timeout=5)
            return (r.stdout or "").splitlines()[0].strip()
        except Exception:
            return ""

