    def _sshd_bin():
        """sshd 真实路径（非 root PATH 里通常没有 /usr/sbin）。"""
        import shutil as _sh
        for c in ("/usr/sbin/sshd", "/usr/local/sbin/sshd", _sh.which("sshd")):
            if c and os.path.exists(c):
                return c
        return "sshd"

    def _ssh_can_sudo():
        """面板进程是否有免密 sudo（决定能否真实改 /etc/ssh 与 systemctl）。"""
        try:
            import subprocess as _sp
            return _sp.run("sudo -n true", shell=True, capture_output=True, timeout=4).returncode == 0
        except Exception:
            return False

    def _ssh_run(cmd):
        """执行系统命令，优先直接执行，失败则 sudo -n 重试；返回 (rc, stdout, stderr) 真实值。"""
        import subprocess as _sp
        try:
            r = _sp.run(cmd, shell=True, capture_output=True, text=True, timeout=20)
            if r.returncode == 0:
                return 0, r.stdout, r.stderr
            if _ssh_can_sudo():
                r2 = _sp.run("sudo -n " + cmd, shell=True, capture_output=True, text=True, timeout=30)
                return r2.returncode, r2.stdout, r2.stderr
            return r.returncode, r.stdout, r.stderr
        except Exception as e:
            return 255, "", str(e)

    def _ssh_write_cfg(path, text):
        """写入 sshd 配置文件（直写失败则 sudo -n tee）。返回 (ok, err)。"""
        try:
            with open(path, "w") as f:
                f.write(text)
            return True, ""
        except Exception as e1:
            import subprocess as _sp
            try:
                r = _sp.run(["sudo", "-n", "tee", path], input=text, capture_output=True, text=True, timeout=15)
                if r.returncode == 0:
                    return True, ""
                return False, "无写权限(uid=%d)且 sudo -n 失败: %s" % (os.getuid(), (r.stderr or str(e1)).strip()[:200])
            except Exception as e2:
                return False, "写入失败: %s / %s" % (e1, e2)

    def _ssh_keys_payload():
        import glob as _g, tempfile as _tf, subprocess as _sp
        hosts, auth = [], []
        for pub in sorted(_g.glob("/etc/ssh/ssh_host_*_key.pub")):
            try:
                r = _sp.run(["ssh-keygen", "-lf", pub], capture_output=True, text=True, timeout=6)
            except Exception:
                continue
            pr = (r.stdout or "").split()
            if not pr: continue
            hosts.append({"file": os.path.basename(pub), "bits": pr[0],
                          "fp": pr[1] if len(pr) > 1 else "",
                          "type": (pr[3].strip("()") if len(pr) > 3 else "")})
        ak = os.path.expanduser("~/.ssh/[authorized-keys]")
        if os.path.exists(ak):
            for i, l in enumerate(open(ak).read().splitlines(), 1):
                ls = l.strip()
                if not ls or ls.startswith("#"): continue
                pr = ls.split()
                fp = ""
                try:
                    with _tf.NamedTemporaryFile("w", suffix=".pub", delete=False) as tf:
                        tf.write(ls + "\n"); tp = tf.name
                    r = _sp.run(["ssh-keygen", "-lf", tp], capture_output=True, text=True, timeout=6)
                    os.unlink(tp)
                    fp = ((r.stdout or "").split() + ["", ""])[1]
                except Exception:
                    fp = ""
                auth.append({"line": i, "type": pr[0] if pr else "", "fp": fp,
                             "comment": (" ".join(pr[2:]) if len(pr) > 2 else ""), "raw": ls})
        return {"ok": True, "hostkeys": hosts, "authkeys": auth, "path": ak,
                "sshdTest": _ssh_test()}

    def _ssh_test():
        import subprocess as _sp
        try:
            _rc, _o, _e = _ssh_run(_sshd_bin() + " -t")
            return {"ok": _rc == 0, "msg": (_e or _o or "").strip() or "配置语法正确"}
        except Exception as e:
            return {"ok": False, "msg": str(e)}

    @app.get("/api/ssh")
    def api_ssh():
        if not need_auth(): return jsonify({"error":"unauth"}), 401
        """SSH 配置：从 /etc/ssh/sshd_config 真值读取 + 会话/登录日志。"""
        import subprocess, os
        def sh(c):
            try:
                return subprocess.run(c, shell=True, capture_output=True, text=True, timeout=4).stdout.strip()
            except Exception:
                return ""
        # sshd 指令名大小写不敏感（"port" 与 "Port" 等价），统一按标准写法归一，
        # 否则写入时被前端小写化后，读取端会认不出来而回落到内置默认值。
        _CANON = {x.lower(): x for x in (
            "Port", "ListenAddress", "PermitRootLogin", "PasswordAuthentication",
            "PubkeyAuthentication", "UseDNS", "UsePAM", "X11Forwarding", "PrintMotd",
            "PermitEmptyPasswords", "ChallengeResponseAuthentication",
            "KbdInteractiveAuthentication", "GSSAPIAuthentication", "ClientAliveInterval",
            "ClientAliveCountMax", "LoginGraceTime", "MaxAuthTries", "MaxSessions",
            "PermitTunnel", "AllowTcpForwarding", "GatewayPorts", "X11UseLocalhost",
            "Subsystem", "AcceptEnv", "Banner", "Include", "Match", "LogLevel",
            "AuthorizedKeysFile", "StrictModes", "TCPKeepAlive", "Compression")}
        def _canon(name):
            return _CANON.get(name.lower(), name)
        # Match 感知解析：顶层(Main) / Match all(全局生效) / 条件 Match(按来源覆盖) 三层分别记录
        cfg = {"Main": {}, "All": {}, "Cond": {}}
        _ctx, _cond = "Main", []
        _lines = open("/etc/ssh/sshd_config").read().splitlines() if os.path.exists("/etc/ssh/sshd_config") else []
        for l in _lines:
            ls = l.strip()
            if not ls or ls.startswith("#"): continue
            pr = ls.split(None, 1)
            if pr[0].lower() == "match":
                crit = (pr[1] if len(pr) > 1 else "").strip()
                if crit.lower() == "all":
                    _ctx, _cond = "All", []
                else:
                    _ctx, _cond = "Cond", [crit]
                continue
            if len(pr) < 2: continue
            k, v = _canon(pr[0]), pr[1].strip()
            if _ctx == "Cond":
                cfg["Cond"].setdefault(_cond[0], {}).setdefault(k, []).append(v)
            else:
                cfg[_ctx].setdefault(k, []).append(v)

        # 真实生效值：sshd -T 会把 Include 进来的 drop-in 与 Match 规则一起算进去，
        # 比手写解析准确（例如 /etc/ssh/sshd_config.d/50-cloud-init.conf 里的
        # PasswordAuthentication yes 会覆盖主文件、并作用于 Match 之后的所有连接）。
        _eff = {}
        try:
            import subprocess as _sp
            _rr = _sp.run("sudo -n %s -T" % _sshd_bin(), shell=True, capture_output=True, text=True, timeout=15)
            if _rr.returncode != 0:
                _rr = _sp.run("%s -T" % _sshd_bin(), shell=True, capture_output=True, text=True, timeout=15)
            for _l in (_rr.stdout or "").splitlines():
                _pr = _l.split(None, 1)
                if len(_pr) < 2: continue
                _eff.setdefault(_pr[0].lower(), []).append(_pr[1].strip())
        except Exception:
            _eff = {}

        def _eff_one(k, default=None):
            v = _eff.get(k.lower())
            if v:
                if k.lower() == "port":
                    out = []
                    for x in v:
                        if x not in out: out.append(x)
                    return ", ".join(out)
                if k.lower() == "listenaddress":
                    # sshd -T 输出的是 地址:端口 的笛卡尔积，页面「监听地址」只展示地址
                    out = []
                    for x in v:
                        a = x.rsplit(":", 1)[0] if ":" in x else x
                        if a not in out: out.append(a)
                    return ", ".join(out)
                return v[0]
            return default

        def one(k, default=None):
            """有效值：Main 优先，其次 Match all，再次 sshd 内置默认。"""
            for scope in ("Main", "All"):
                v = cfg[scope].get(k) or cfg[scope].get(_canon(k))
                if v: return (", ".join(v) if k == "Port" else v[-1])
            if default is not None: return default
            if k == "Port": return "22"
            if k == "ListenAddress": return "-"
            if k == "PermitRootLogin": return "prohibit-password"
            if k in ("PasswordAuthentication", "PubkeyAuthentication"): return "yes"
            if k == "UseDNS": return "yes"
            return "-"

        # 条件 Match 覆盖项（列出来，避免「设置里显示 yes、实际按来源是 no」的误导）
        cond_over = []
        for crit, kv in cfg["Cond"].items():
            for k, vs in kv.items():
                cond_over.append({"match": crit, "key": k, "val": vs[-1]})
        raw = sh("who").replace("\x00", "")
        sess = []
        for line in raw.splitlines():
            parts = line.split()
            if len(parts) < 3: continue
            user, tty = parts[0], parts[1]
            rest = " ".join(parts[2:])
            ip, when = "", rest
            if rest.endswith(")") and "(" in rest:
                when, ip = rest.rsplit("(", 1)
                ip = ip.rstrip(")")
            sess.append({"user": user, "tty": tty, "ip": ip or "-", "date": when.strip()})
        if not sess:
            raw = "(当前无登录会话)"
        active = sh("systemctl is-active ssh 2>/dev/null") or "inactive"
        enabled = sh("systemctl is-enabled ssh 2>/dev/null") or "disabled"
        logins = sh("last -n 8 2>/dev/null| grep -v '^$' | tr -s ' '")
        # 会话带 pid（who -u 的真实 pid 列），供「强制下线」使用
        sess2 = []
        try:
            import re as _re
            wu = sh("who -u")
            for line in wu.splitlines():
                m = _re.match(r"^(\S+)\s+(\S+)\s+(\d{4}-\d{2}-\d{2} \d{2}:\d{2})\s+(\S+)\s+(\d+)(?:\s+\((.*)\))?", line)
                if not m: continue
                sess2.append({"user": m.group(1), "tty": m.group(2), "date": m.group(3),
                              "idle": m.group(4), "pid": int(m.group(5)), "ip": m.group(6) or "-"})
        except Exception:
            sess2 = []
        # 全部生效配置（带行号，供「全部配置」tab）
        cfgall = []
        try:
            for i, l in enumerate(open("/etc/ssh/sshd_config").read().splitlines(), 1):
                ls = l.strip()
                if not ls or ls.startswith("#"): continue
                pr = ls.split(None, 1)
                cfgall.append({"line": i, "key": pr[0], "val": (pr[1].strip() if len(pr) > 1 else "")})
        except Exception:
            cfgall = []
        # 主机密钥指纹（真实 ssh-keygen -lf）
        import glob as _glob
        hostkeys = []
        for pub in sorted(_glob.glob("/etc/ssh/ssh_host_*_key.pub")):
            o = sh("ssh-keygen -lf %s 2>/dev/null" % pub)
            pr = o.split()
            if not pr: continue
            hostkeys.append({"file": os.path.basename(pub), "bits": pr[0],
                             "fp": pr[1] if len(pr) > 1 else "",
                             "type": (pr[3].strip("()") if len(pr) > 3 else "")})
        # 授权密钥（读 ~/.ssh/ [authorized-keys]+ 逐条算指纹）
        import tempfile as _tf
        ak = os.path.expanduser("~/.ssh/[authorized-keys]")
        authkeys = []
        try:
            if os.path.exists(ak):
                for i, l in enumerate(open(ak).read().splitlines(), 1):
                    ls = l.strip()
                    if not ls or ls.startswith("#"): continue
                    pr = ls.split()
                    fp = ""
                    try:
                        with _tf.NamedTemporaryFile("w", suffix=".pub", delete=False) as tf:
                            tf.write(ls + "\n"); tp = tf.name
                        fo = sh("ssh-keygen -lf %s 2>/dev/null" % tp)
                        os.unlink(tp)
                        fp = (fo.split()[1] if len(fo.split()) > 1 else "")
                    except Exception:
                        fp = ""
                    authkeys.append({"line": i, "type": pr[0] if pr else "", "fp": fp,
                                     "comment": (" ".join(pr[2:]) if len(pr) > 2 else ""), "raw": ls})
        except Exception:
            authkeys = []
        # sshd 配置语法自检（真实 sshd -t）
        try:
            import subprocess as _sp
            _rc, _o, _e = _ssh_run(_sshd_bin() + " -t")
            sshd_test = {"ok": _rc == 0, "msg": (_e or _o or "").strip() or "配置语法正确"}
        except Exception as e:
            sshd_test = {"ok": False, "msg": str(e)}
        return jsonify({
            "port": _eff_one("Port") or one("Port"),
            "listen": _eff_one("ListenAddress") or one("ListenAddress"),
            "root": _eff_one("PermitRootLogin") or one("PermitRootLogin"),
            "pwd": _eff_one("PasswordAuthentication") or one("PasswordAuthentication"),
            "key": _eff_one("PubkeyAuthentication") or one("PubkeyAuthentication"),
            "dns": _eff_one("UseDNS") or one("UseDNS"),
            "active": active, "enabled": enabled, "sess": sess2 or sess,
            "sessions": raw, "logins": logins or "(暂无登录记录)",
            "cfgAll": cfgall, "hostkeys": hostkeys, "authkeys": authkeys,
            "condOver": cond_over,
            "sshdTest": sshd_test,
            "writable": os.access("/etc/ssh/sshd_config", os.W_OK),
            "sudo": _ssh_can_sudo(),
            "cfgPath": "/etc/ssh/sshd_config"})

    @app.post("/api/ssh/service")
    def api_ssh_service():
        """SSH 服务启停 / 开机自启：执行 systemctl(必要时 sudo -n)，回显真实返回码与 stderr。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(silent=True) or {}
        action = d.get("action")
        unit = {"start": "start", "stop": "stop", "restart": "restart",
                "boot-on": "enable", "boot-off": "disable"}.get(action)
        if not unit:
            return jsonify({"ok": False, "error": "未知操作"})
        rc, out, err = _ssh_run("systemctl %s ssh" % unit)
        if rc != 0:
            # 真实失败：回显 systemctl 的原始错误
            return jsonify({"ok": False, "error": "systemctl %s ssh 失败(exit %d): %s" % (unit, rc, (err or out or "").strip()[:400])})
        _, act, _ = _ssh_run("systemctl is-active ssh")
        _, en, _ = _ssh_run("systemctl is-enabled ssh")
        return jsonify({"ok": True, "msg": "SSH %s 成功" % {"start": "启动", "stop": "关闭", "restart": "重启",
                                                              "boot-on": "已设开机自启", "boot-off": "已取消开机自启"}[action],
                        "active": act.strip(), "enabled": en.strip()})

    @app.post("/api/ssh/restart")
    def api_ssh_restart():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"}), 403
        rc, out, err = _ssh_run("systemctl restart ssh")
        if rc != 0:
            return jsonify({"ok": False, "error": "systemctl restart ssh 失败(exit %d): %s" % (rc, (err or out or "").strip()[:400])})
        return jsonify({"ok": True, "msg": "sshd 已重启"})

    @app.post("/api/ssh/session")
    def api_ssh_session():
        """强制下线某个真实登录会话 {action:'kill', pid}。pid 必须出现在 who -u 中，避免任意杀进程。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(silent=True) or {}
        if d.get("action") != "kill":
            return jsonify({"ok": False, "error": "未知操作"})
        try:
            pid = int(d.get("pid"))
        except Exception:
            return jsonify({"ok": False, "error": "缺少会话 pid"})
        rc, out, err = _ssh_run("who -u")
        if not re.search(r"\s%d(\s|$)" % pid, out or ""):
            return jsonify({"ok": False, "error": "会话 %d 已不存在（未在 who -u 中）" % pid})
        tty = re.sub(r"[^A-Za-z0-9/._-]", "", str(d.get("tty") or ""))
        cmd = ("pkill -HUP -t %s" % tty) if tty else ("kill -HUP %d" % pid)
        rc, out, err = _ssh_run(cmd)
        if rc != 0:
            return jsonify({"ok": False, "error": "下线失败(exit %d): %s" % (rc, (err or out or "").strip()[:300])})
        _op_log("hosts", "edit", status="Success", detail_zh="强制下线 SSH 会话 pid=%d" % pid, detail_en="Kill SSH session")
        return jsonify({"ok": True, "msg": "会话 %d 已强制下线" % pid})

    @app.get("/api/ssh/keys")
    def api_ssh_keys():
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        return jsonify(_ssh_keys_payload())

    @app.post("/api/ssh/keys")
    def api_ssh_keys_write():
        """授权密钥增删（写 ~/.ssh/[authorized-keys]）。{action:'add'|'del', key|raw}"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(silent=True) or {}
        act = d.get("action")
        ak = os.path.expanduser("~/.ssh/[authorized-keys]")
        os.makedirs(os.path.dirname(ak), exist_ok=True)
        lines = open(ak).read().splitlines() if os.path.exists(ak) else []
        if act == "add":
            k = str(d.get("key") or "").strip()
            if not k or "\n" in k:
                return jsonify({"ok": False, "error": "公钥内容为空或包含换行"})
            if not re.match(r"^(ssh-(rsa|ed25519|dss)|ecdsa-sha2-nistp\d+|sk-ssh-ed25519@openssh\.com)\s+AAAA", k):
                return jsonify({"ok": False, "error": "不是合法的 OpenSSH 公钥（应以 ssh-rsa / ssh-ed25519 / ecdsa-sha2-* 开头）"})
            try:
                import tempfile as _tf, subprocess as _sp
                with _tf.NamedTemporaryFile("w", suffix=".pub", delete=False) as tf:
                    tf.write(k + "\n"); tp = tf.name
                chk = _sp.run(["ssh-keygen", "-lf", tp], capture_output=True, text=True)
                os.unlink(tp)
                if chk.returncode != 0:
                    return jsonify({"ok": False, "error": "公钥无法解析: " + (chk.stderr or "").strip()[:200]})
            except Exception as e:
                return jsonify({"ok": False, "error": "公钥校验异常: " + str(e)})
            if k in [x.strip() for x in lines]:
                return jsonify({"ok": False, "error": "该公钥已存在，未重复添加"})
            lines.append(k)
            open(ak, "w").write("\n".join(lines) + "\n")
            try: os.chmod(ak, 0o600)
            except Exception: pass
            _op_log("hosts", "create", status="Success", detail_zh="新增 SSH 授权密钥", detail_en="Add authorized key")
            return jsonify({"ok": True, "msg": "已追加到 [authorized-keys]（%d 条）" % len(lines)})
        if act == "del":
            raw = str(d.get("raw") or "").strip()
            if not raw:
                return jsonify({"ok": False, "error": "缺少要删除的密钥"})
            keep = [x for x in lines if x.strip() != raw]
            if len(keep) == len(lines):
                return jsonify({"ok": False, "error": "未找到该密钥"})
            if not keep:
                return jsonify({"ok": False, "error": "拒绝删除最后一条授权密钥（会导致无法登录）"})
            open(ak, "w").write("\n".join(keep) + "\n")
            try: os.chmod(ak, 0o600)
            except Exception: pass
            _op_log("hosts", "delete", status="Success", detail_zh="删除 SSH 授权密钥", detail_en="Delete authorized key")
            return jsonify({"ok": True, "msg": "已删除，剩余 %d 条" % len(keep)})
        return jsonify({"ok": False, "error": "未知操作"})

    @app.post("/api/ssh/set")
    def api_ssh_set():
        """真实改写 /etc/ssh/sshd_config 单项配置：写入 → sshd -t 校验 → 失败自动回滚 → reload。"""
        if not need_auth(): return jsonify({"error": "unauth"}), 401
        if not _can_write(request.headers):
            return jsonify({"ok": False, "error": "无写入权限"}), 403
        d = request.get_json(silent=True) or {}
        key = str(d.get("key") or "").strip()
        val = str(d.get("val") or "").strip()
        _ALIAS = {"port": "Port", "listen": "ListenAddress", "root": "PermitRootLogin",
                  "pwd": "PasswordAuthentication", "key": "PubkeyAuthentication",
                  "dns": "UseDNS"}
        key = _ALIAS.get(key.lower(), key)
        path = "/etc/ssh/sshd_config"
        if not re.match(r"^[A-Za-z][A-Za-z0-9]*$", key):
            return jsonify({"ok": False, "error": "配置项名称不合法"})
        if "\n" in val or "\r" in val:
            return jsonify({"ok": False, "error": "配置值不能包含换行"})
        _vals = [x.strip() for x in val.split(",") if x.strip()]
        if key.lower() == "port":
            if not _vals or any(not x.isdigit() or not (0 < int(x) < 65536) for x in _vals):
                return jsonify({"ok": False, "error": "端口必须为 1-65535 的数字，多个端口用英文逗号分隔"})
            seen, _uniq = set(), []
            for x in _vals:
                if x not in seen: seen.add(x); _uniq.append(x)
            _vals = _uniq
        if not os.path.exists(path):
            return jsonify({"ok": False, "error": "配置文件不存在: " + path})
        try:
            orig = open(path).read()
        except Exception as e:
            return jsonify({"ok": False, "error": "读取失败: " + str(e)})
        out, found, _emitted = [], False, False
        _use_key = key
        _in_match = False
        _first_match_at = None
        for l in orig.splitlines():
            ls = l.strip()
            if ls and not ls.startswith("#") and ls.split(None, 1)[0].lower() == "match":
                if _first_match_at is None: _first_match_at = len(out)
                _in_match = True
            if (not _in_match) and ls and not ls.startswith("#") \
                    and ls.split(None, 1)[0].lower() == key.lower():
                found = True
                if _emitted: continue          # 多值指令：合并成连续多行，去掉旧重复行
                _emitted = True
                _use_key = ls.split(None, 1)[0]    # 沿用原文件写法（Port 不改写成 port）
                for x in _vals:
                    out.append("%s %s" % (_use_key, x))
            else:
                out.append(l)
        if not found:
            # 主配置区里没有该指令：插到第一个 Match 之前（不能追加到文件末尾，
            # 那样新指令会落进最后一个 Match 块、只对某个条件生效）
            _std = {"port": "Port", "listenaddress": "ListenAddress", "permitrootlogin": "PermitRootLogin",
                    "passwordauthentication": "PasswordAuthentication", "pubkeyauthentication": "PubkeyAuthentication",
                    "usedns": "UseDNS", "usepam": "UsePAM", "x11forwarding": "X11Forwarding"}
            _use_key = _std.get(key.lower(), key)
            _new = ["%s %s" % (_use_key, x) for x in _vals]
            _at = len(out) if _first_match_at is None else _first_match_at
            out[_at:_at] = _new
        newtext = "\n".join(out) + "\n"
        ok, err = _ssh_write_cfg(path, newtext)
        if not ok:
            return jsonify({"ok": False, "error": err})
        rc, o2, e2 = _ssh_run(_sshd_bin() + " -t")
        if rc != 0:
            _ssh_write_cfg(path, orig)   # 真实回滚
            return jsonify({"ok": False, "error": "sshd -t 校验失败，已回滚: " + (e2 or o2).strip()[:400]})
        rc, o3, e3 = _ssh_run("systemctl reload ssh")
        warn = None if rc == 0 else ("配置已写入并通过 sshd -t，但 reload 失败(exit %d): %s" % (rc, (e3 or o3).strip()[:200]))
        _op_log("hosts", "edit", status="Success", detail_zh="修改 SSH 配置 %s=%s" % (key, val or "(清空)"), detail_en="Update sshd config")
        _shown = ("%s 已清空" % key) if not val else ("%s 已设为 %s" % (key, val))
        return jsonify({"ok": True, "warn": warn, "msg": _shown + ("（已 reload）" if rc == 0 else "")})

    _cert_autorenew_worker()   # 面板内置证书自动续签守护(每 6h 扫一次)

    return app

